// questions-cloud-devops.js
// Cyber Defense Runner - Cloud & DevOps question bank (100 questions).
// Standalone data file. NOT yet merged into questions.js.
// Distribution: tiers 50 Beginner / 35 Intermediate / 15 Advanced.
//               correct index balanced 25 / 25 / 25 / 25 across A/B/C/D.

const CLOUD_DEVOPS_QUESTIONS = [
  { id:"cloud-devops-001", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does 'the cloud' generally refer to?", options:["Computing resources like servers and storage provided over the internet on demand","A weather system that predicts coming storms","Local hard drives installed inside your own PC","Magnetic backup tapes kept in a storage cabinet"], correct:0, explain:"Cloud computing delivers servers, storage, and services over the internet, often on demand.", reward:"Cloud Basics" },
  { id:"cloud-devops-002", tier:"Beginner", topic:"Cloud & DevOps", prompt:"In the cloud shared responsibility model, who secures the customer's own data and access settings?", options:["The cloud provider alone","The customer","Nobody","The internet provider"], correct:1, explain:"Providers secure the infrastructure, but customers remain responsible for their data, identities, and configurations.", reward:"Responsibility Sense" },
  { id:"cloud-devops-003", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does IAM (Identity and Access Management) control?", options:["How fast the internet connection runs","How much disk storage is available","Which colors the screen displays","Who can access which cloud resources and what they can do"], correct:3, explain:"IAM manages identities and their permissions, controlling access to cloud resources.", reward:"Access Control" },
  { id:"cloud-devops-004", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a cloud 'storage bucket'?", options:["A physical pail used for water","A particular type of computer CPU","A container for storing files or objects in the cloud","A standard network patch cable"], correct:2, explain:"A bucket is cloud object storage that holds files (objects), commonly used for data and backups.", reward:"Storage Sense" },
  { id:"cloud-devops-005", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a 'container' in computing?", options:["A large metal shipping crate used for cargo at sea","A lightweight package that bundles an app with its dependencies to run consistently","A particular type of widescreen computer monitor","A spare disk drive used only for storing backups"], correct:1, explain:"A container packages an application and its dependencies so it runs the same across environments.", reward:"Container Basics" },
  { id:"cloud-devops-006", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is Docker commonly used for?", options:["Building and running containers","Editing photos","Sending email","Designing logos"], correct:0, explain:"Docker is a popular tool for building, sharing, and running containers.", reward:"Container Basics" },
  { id:"cloud-devops-007", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does Kubernetes mainly do?", options:["Edits text documents and files","Plays back music and audio","Orchestrates and manages containers at scale","Stores account passwords safely"], correct:2, explain:"Kubernetes automates deploying, scaling, and managing containerized applications.", reward:"Orchestration Sense" },
  { id:"cloud-devops-008", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does a CI/CD pipeline help automate?", options:["Coffee making","Photo editing","Weather forecasts","Building, testing, and deploying code"], correct:3, explain:"CI/CD pipelines automate integrating, testing, and delivering software changes.", reward:"Pipeline Sense" },
  { id:"cloud-devops-009", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is Git used for?", options:["Tracking changes to code over time (version control)","Cooling down the computer's CPU","Encrypting the office Wi-Fi network","Designing new computer hardware"], correct:0, explain:"Git is a version control system that tracks code changes and supports collaboration.", reward:"Version Control" },
  { id:"cloud-devops-010", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should secrets like API keys NOT be hard-coded in source code?", options:["Hard-coding makes the code longer","Anyone with the code could read and misuse them","Hard-coding slows down compiling","Stored keys change the app's colors"], correct:1, explain:"Hard-coded secrets can be exposed to anyone who sees the code, so use a secrets manager instead.", reward:"Secret Safety" },
  { id:"cloud-devops-011", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is 'infrastructure as code' (IaC)?", options:["Literally writing program code on paper","A particular type of network firewall","A specific file format used for backups","Defining and managing infrastructure using configuration files"], correct:3, explain:"IaC defines servers and resources in config files so they can be created consistently and repeatably.", reward:"IaC Sense" },
  { id:"cloud-devops-012", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why is monitoring important for cloud systems?", options:["To choose color themes for dashboards","To deliberately slow the systems down","To detect problems, outages, and unusual activity early","To delete data that is not needed"], correct:2, explain:"Monitoring watches health and behavior so issues and anomalies are caught quickly.", reward:"Monitoring Focus" },
  { id:"cloud-devops-013", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why are logs valuable in cloud environments?", options:["They generally look quite nice on screen","They record events for troubleshooting and investigating issues","They speed up the busy cloud servers","They store large image and photo files"], correct:1, explain:"Logs capture what happened, supporting debugging, auditing, and incident investigation.", reward:"Log Sense" },
  { id:"cloud-devops-014", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What are environment variables often used for in applications?", options:["Holding configuration values, like settings, outside the code","Painting bright colors onto the screen","Cooling down the busy cloud server","Encrypting the entire disk drive at rest"], correct:0, explain:"Environment variables store configuration such as settings or secrets separately from code.", reward:"Config Sense" },
  { id:"cloud-devops-015", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Applying least privilege to a cloud account means what?", options:["Give it full administrator rights","Give it no access at all","Grant only the permissions it needs for its task","Share it with everyone in the team"], correct:2, explain:"Least privilege grants only the access required, limiting damage if the account is misused.", reward:"Access Control" },
  { id:"cloud-devops-016", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why can deploying changes straight to production be risky?", options:["Deploying directly is far too slow","Direct deploys use up more disk","Such deploys make the UI colorful","Untested changes can break the live system users depend on"], correct:3, explain:"Deploying untested changes to production can cause outages or bugs affecting real users.", reward:"Deploy Safety" },
  { id:"cloud-devops-017", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does a 'rollback' do after a bad deployment?", options:["Restores the previous working version","Deletes all data","Speeds up the CPU","Encrypts the app"], correct:0, explain:"A rollback reverts to the last known-good version to quickly recover from a faulty release.", reward:"Rollback Sense" },
  { id:"cloud-devops-018", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does container 'image scanning' check for?", options:["Nicer colors used in the image","Known vulnerabilities or issues in the image","Faster image download speeds","Bigger fonts shown on screen"], correct:1, explain:"Image scanning inspects container images for known vulnerabilities and risky contents before use.", reward:"Image Safety" },
  { id:"cloud-devops-019", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a container 'registry'?", options:["A printed guest list for events","A particular type of CPU chip","A standard network patch cable","A place to store and share container images"], correct:3, explain:"A registry stores and distributes container images so they can be pulled for deployment.", reward:"Registry Sense" },
  { id:"cloud-devops-020", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why keep development and production environments separate?", options:["Creating much nicer company logos","To deliberately use up more servers","So testing and mistakes in dev don't affect live users","To slow the whole process down"], correct:2, explain:"Separating dev from prod keeps experiments and bugs away from the live system real users rely on.", reward:"Environment Sense" },
  { id:"cloud-devops-021", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Which is a common benefit of cloud computing?", options:["Heavier hardware","Scaling resources up or down as needed","Slower deployments","No internet ever needed"], correct:1, explain:"The cloud lets you scale resources on demand, paying for what you use.", reward:"Cloud Basics" },
  { id:"cloud-devops-022", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"A company leaves a cloud bucket public by mistake. Whose responsibility was that setting?", options:["The customer's, since they control their configurations","The cloud provider's own team alone","Nobody at all is responsible for it","The internet service provider's staff"], correct:0, explain:"Customers are responsible for their own configuration choices, like bucket access settings.", reward:"Responsibility Sense" },
  { id:"cloud-devops-023", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why assign cloud permissions to roles or groups rather than each person individually?", options:["It mainly gives roles nicer names","It deliberately slows down logins","It is easier to manage and keeps access consistent","It ends up using more storage"], correct:2, explain:"Role and group-based access simplifies management and keeps permissions consistent and reviewable.", reward:"Access Control" },
  { id:"cloud-devops-024", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is a common cause of cloud data leaks from storage buckets?", options:["Using far too much encryption","Generally slow network speeds","Storing only very small files","Buckets accidentally left publicly accessible"], correct:3, explain:"Misconfigured public buckets are a frequent cause of accidental data exposure.", reward:"Storage Sense" },
  { id:"cloud-devops-025", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why do containers help apps run the same in dev and production?", options:["They bundle the app with its dependencies and environment","They simply rely on a kind of magic","They need no application code at all","They delete the differences at random"], correct:0, explain:"By packaging dependencies together, containers reduce 'works on my machine' inconsistencies.", reward:"Container Basics" },
  { id:"cloud-devops-026", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a Docker 'image'?", options:["An ordinary saved photo image file","A read-only template used to create running containers","A particular type of computer monitor","A network activity log file on disk"], correct:1, explain:"A Docker image is a packaged template; running it creates a container instance.", reward:"Container Basics" },
  { id:"cloud-devops-027", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"In Kubernetes, what is a 'pod'?", options:["A cloud object storage bucket service","One ordinary cloud user account login","A network firewall security appliance","The smallest deployable unit, holding one or more containers"], correct:3, explain:"A pod is Kubernetes' smallest unit and wraps one or more closely related containers.", reward:"Orchestration Sense" },
  { id:"cloud-devops-028", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why run automated tests in a CI pipeline?", options:["To deliberately slow down the releases","Mainly just for simple decoration","To catch bugs early before changes are merged or deployed","To end up using much more disk space"], correct:2, explain:"Automated tests in CI catch problems early, improving quality before deployment.", reward:"Pipeline Sense" },
  { id:"cloud-devops-029", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a Git 'commit'?", options:["A full deletion of all the code","A saved snapshot of changes with a message","A particular type of server","A secret account password"], correct:1, explain:"A commit records a snapshot of changes along with a message describing them.", reward:"Version Control" },
  { id:"cloud-devops-030", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is a safer way to give a pipeline access to a secret at runtime?", options:["Store it in a secrets manager and inject it when the job runs","Print it directly into the build logs","Email it to everyone on the whole team","Hard-code it inside the code repo"], correct:0, explain:"Secrets managers store secrets securely and provide them to pipelines only when needed.", reward:"Secret Safety" },
  { id:"cloud-devops-031", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"A benefit of infrastructure as code is...?", options:["A whole lot more manual clicking work","Random and inconsistent server setups","Repeatable, version-controlled, consistent infrastructure","Much slower overall resource provisioning"], correct:2, explain:"IaC makes infrastructure repeatable and reviewable, reducing manual error and drift.", reward:"IaC Sense" },
  { id:"cloud-devops-032", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is an 'alert' in cloud monitoring?", options:["A scheduled backup of important data","A color theme for the dashboard UI","A stored system log file on disk","A notification triggered when a metric crosses a threshold"], correct:3, explain:"Alerts fire when monitored conditions, like high errors or CPU, cross set thresholds.", reward:"Monitoring Focus" },
  { id:"cloud-devops-033", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why centralize logs from many cloud services?", options:["To search and correlate events across services in one place","To delete all the logs much faster","To hide the logs from the auditors","To slow the whole cloud system down"], correct:0, explain:"Central logging lets you search and connect events across services for troubleshooting and security.", reward:"Log Sense" },
  { id:"cloud-devops-034", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why is putting a database password in an environment variable better than in code?", options:["It makes the source code look shorter","It keeps the secret out of the source code and version history","It makes the whole app run faster","It uses up less server memory overall"], correct:1, explain:"Keeping secrets in env vars or a vault avoids committing them into code and history.", reward:"Config Sense" },
  { id:"cloud-devops-035", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why avoid giving every developer full production admin access?", options:["Full admin access is generally slower to use","Granting it to everyone simply looks bad","Such broad access uses up more storage space","Broad access increases the risk and blast radius of mistakes or compromise"], correct:3, explain:"Limiting production access reduces the chance and impact of accidental or malicious changes.", reward:"Access Control" },
  { id:"cloud-devops-036", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What does a 'canary' or gradual rollout help with?", options:["Designing brand-new company logos for the site","Cooling down the busy cloud servers physically","Releasing to a small group first to catch problems before full rollout","Deleting the old and unused system log files"], correct:2, explain:"Gradual rollouts expose changes to a few users first, limiting impact if something breaks.", reward:"Deploy Safety" },
  { id:"cloud-devops-037", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why keep previous versions available after deploying?", options:["Mainly just for simple decoration","So you can quickly roll back if the new version fails","To use up much more disk for fun","To deliberately slow the deploys"], correct:1, explain:"Retaining prior versions enables a fast rollback when a release misbehaves.", reward:"Rollback Sense" },
  { id:"cloud-devops-038", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why scan container images before deploying them?", options:["To catch vulnerabilities or malware before they reach production","To make the container images look prettier","To deliberately slow down the deploys","To rename all of the container images"], correct:0, explain:"Scanning catches known vulnerabilities or bad contents before images run in production.", reward:"Image Safety" },
  { id:"cloud-devops-039", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why restrict who can push images to a container registry?", options:["To give the images much nicer names","To help the registry save some power","To prevent untrusted or malicious images from being deployed","To deliberately slow down image pulls"], correct:2, explain:"Limiting push access stops unauthorized or tampered images from entering your deployments.", reward:"Registry Sense" },
  { id:"cloud-devops-040", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should production secrets differ from development secrets?", options:["Using up much more storage space","To give the secrets nicer names","To deliberately slow down logins","So a leak of dev secrets doesn't expose production"], correct:3, explain:"Separate secrets ensure a dev leak can't be used against the live production system.", reward:"Environment Sense" },
  { id:"cloud-devops-041", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does 'on-demand' mean in cloud services?", options:["You can get resources when you need them, without buying hardware upfront","You always have to wait several long weeks","You personally own the entire physical data center","You never need any kind of account at all"], correct:0, explain:"On-demand means provisioning resources as needed, paying for usage rather than owning hardware.", reward:"Cloud Basics" },
  { id:"cloud-devops-042", tier:"Beginner", topic:"Cloud & DevOps", prompt:"In shared responsibility, what does the cloud provider typically handle?", options:["Your own personal account passwords","The security of the underlying physical infrastructure","Classifying all of your stored data","Setting all of your user permissions"], correct:1, explain:"Providers secure the physical and foundational infrastructure; customers handle their data and access.", reward:"Responsibility Sense" },
  { id:"cloud-devops-043", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is an IAM 'policy'?", options:["A scheduled data backup plan for files","A standard network patch cable","A particular monitor brightness setting","A set of rules defining what actions an identity can perform"], correct:3, explain:"An IAM policy specifies which actions an identity may take on which resources.", reward:"Access Control" },
  { id:"cloud-devops-044", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why enable encryption on cloud storage buckets?", options:["Deliberately slowing down all access","To give the buckets much nicer names","So stored data is unreadable if accessed without authorization","To end up using much more storage space"], correct:2, explain:"Encryption protects stored data so it can't be easily read if exposed or stolen.", reward:"Storage Sense" },
  { id:"cloud-devops-045", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why is running a container as root (full privileges) risky?", options:["Running as root is generally much slower","If compromised, the attacker may gain broad control of the host","Root containers use up more disk space","Running as root simply looks a bit bad"], correct:1, explain:"Running as root increases impact if the container is breached; use least privilege instead.", reward:"Container Basics" },
  { id:"cloud-devops-046", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is a Dockerfile?", options:["A set of instructions describing how to build a container image","A stored system log file kept on disk","A secure vault for storing passwords","A network architecture diagram on paper"], correct:0, explain:"A Dockerfile lists the steps to build a container image reproducibly.", reward:"Container Basics" },
  { id:"cloud-devops-047", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why is exposing the Kubernetes dashboard or API publicly risky?", options:["It is generally quite slow to load up","It mainly just looks rather colorful","It can let attackers control the cluster if not protected","It uses up extra cloud storage space"], correct:2, explain:"An exposed cluster control plane can give attackers wide control, so restrict and authenticate access.", reward:"Orchestration Sense" },
  { id:"cloud-devops-048", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why protect the CI/CD pipeline itself as a sensitive system?", options:["It mainly just produces nicer build logs","It deliberately slows down the builds","It is mostly there just for decoration","It can deploy code and hold secrets, so compromise is high impact"], correct:3, explain:"Pipelines often hold secrets and can push code to production, making them a high-value target.", reward:"Pipeline Sense" },
  { id:"cloud-devops-049", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why review code changes (pull requests) before merging?", options:["To catch bugs and security issues before they reach the main branch","To deliberately slow the developers down","Mainly just for some simple decoration","To end up using much more storage space"], correct:0, explain:"Code review catches mistakes and risky changes before they're merged and shipped.", reward:"Version Control" },
  { id:"cloud-devops-050", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"A secret was accidentally committed to Git history. What is the safest response?", options:["Just ignore it completely for now","Rotate (replace) the secret and remove it from history","Email it to the whole project team","Simply rename the code repo"], correct:1, explain:"Once committed, treat the secret as exposed: rotate it and purge it from history.", reward:"Secret Safety" },
  { id:"cloud-devops-051", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why scan infrastructure-as-code files before applying them?", options:["To make the IaC code look much nicer overall","To deliberately slow down the deploys","To rename all of the cloud resources","To catch insecure settings like open ports before they are deployed"], correct:3, explain:"Scanning IaC catches misconfigurations early, before they create real, exploitable infrastructure.", reward:"IaC Sense" },
  { id:"cloud-devops-052", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why must monitoring alert thresholds be tuned carefully?", options:["Ending up using many more cloud dashboards","To give the alerts much nicer display colors","Too-sensitive alerts cause noise, while too-loose ones miss real problems","To deliberately slow the whole system down"], correct:2, explain:"Well-tuned thresholds catch real issues without drowning teams in false alarms.", reward:"Monitoring Focus" },
  { id:"cloud-devops-053", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why protect the integrity of cloud audit logs?", options:["Producing much nicer looking charts","So they can be trusted as accurate records of who did what","To save some extra storage space","To deliberately slow down access"], correct:1, explain:"Tamper-resistant audit logs remain reliable evidence of actions for security and compliance.", reward:"Log Sense" },
  { id:"cloud-devops-054", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why can environment variables still leak secrets if not handled carefully?", options:["They may appear in logs, error messages, or process listings","They are always fully encrypted at rest","They never store any secrets at all","They delete themselves automatically over time"], correct:0, explain:"Env vars can be exposed via logs, crash dumps, or process inspection, so handle them carefully.", reward:"Config Sense" },
  { id:"cloud-devops-055", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why are short-lived, scoped credentials preferred for cloud automation?", options:["Such credentials look a lot more modern","They generally cost quite a lot less","Limited scope and lifetime reduce damage if they are leaked","Scoped credentials run a little bit faster"], correct:2, explain:"Short-lived, narrowly scoped credentials limit the window and reach of any leak.", reward:"Access Control" },
  { id:"cloud-devops-056", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why is a 'blue-green' deployment useful?", options:["Mainly it gives some much nicer display colors","It helps the cloud servers save more power","It is mostly there just for simple decoration","You can switch traffic to a new version and quickly switch back if it fails"], correct:3, explain:"Blue-green keeps two environments so you can shift traffic and roll back fast if needed.", reward:"Deploy Safety" },
  { id:"cloud-devops-057", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why must database changes be planned carefully for rollback?", options:["Data and schema changes can be hard to reverse, unlike simple code swaps","Such changes are generally quite colorful to view","Such changes are nearly always trivial","Database changes basically never matter at all"], correct:0, explain:"Unlike code, data and schema changes may not reverse cleanly, so plan rollbacks and backups carefully.", reward:"Rollback Sense" },
  { id:"cloud-devops-058", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why is using minimal (slim) base images good for security?", options:["Slim base images simply look a whole lot nicer","Fewer included packages means a smaller attack surface and fewer vulnerabilities","Slim base images tend to run quite a bit slower","They end up using a lot more disk space overall"], correct:1, explain:"Smaller images include less software, reducing potential vulnerabilities to patch and exploit.", reward:"Image Safety" },
  { id:"cloud-devops-059", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why pin or verify image digests rather than just using the 'latest' tag?", options:["Mainly it gives the images much nicer names","It deliberately slows down every single image pull","It is mostly there just for simple decoration work","The latest tag can change unexpectedly, while a digest pins the exact reviewed image"], correct:3, explain:"Pinning a digest guarantees you deploy the specific, verified image rather than a moving tag.", reward:"Registry Sense" },
  { id:"cloud-devops-060", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why avoid using real production data in development environments?", options:["Generally it is a fair bit slower to run","It mainly gives nicer-looking test results","Dev is usually less protected, so real data there increases leak risk","It ends up using more cloud storage space"], correct:2, explain:"Dev environments are often less hardened, so real data there raises the risk of exposure.", reward:"Environment Sense" },
  { id:"cloud-devops-061", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a cloud 'region' or 'availability zone'?", options:["A particular type of data backup","A geographic location where cloud resources run","A specific account login method","A particular type of network cable"], correct:1, explain:"Cloud regions and zones are physical locations hosting resources, used for performance and resilience.", reward:"Cloud Basics" },
  { id:"cloud-devops-062", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"For a customer's own virtual machine in the cloud, patching the guest operating system is usually whose job?", options:["The customer's","The provider's always","Nobody's","The internet provider's"], correct:0, explain:"For VMs, the customer typically patches and maintains the guest OS, while the provider secures the hardware.", reward:"Responsibility Sense" },
  { id:"cloud-devops-063", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does enabling MFA on a cloud admin account add?", options:["Some extra cloud storage space","A noticeably faster login process","A second verification step beyond the password","A much nicer dashboard theme"], correct:2, explain:"MFA requires an extra factor, protecting privileged accounts even if the password leaks.", reward:"Access Control" },
  { id:"cloud-devops-064", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why enable access logging on a storage bucket?", options:["To give the buckets much nicer names","To deliberately slow down all access","To end up using much more storage space","To record who accessed objects, aiding audits and investigations"], correct:3, explain:"Access logs show who read or changed objects, supporting auditing and incident response.", reward:"Storage Sense" },
  { id:"cloud-devops-065", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why are containers often described as 'ephemeral'?", options:["They are often short-lived and replaced rather than fixed in place","They simply never stop running at all","They store all of their data forever","They can never be restarted once stopped"], correct:0, explain:"Containers are typically disposable: replaced with fresh ones rather than patched live.", reward:"Container Basics" },
  { id:"cloud-devops-066", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why avoid baking secrets into a Docker image?", options:["Baking secrets makes images smaller","Anyone who pulls the image could extract the secret","Baking them in is much faster","Stored secrets change the UI colors"], correct:1, explain:"Secrets in an image can be read by anyone with the image; inject them at runtime instead.", reward:"Container Basics" },
  { id:"cloud-devops-067", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What does a Kubernetes 'namespace' help with?", options:["Making the pods start up faster","Producing nicer cluster log files","Creating bigger cluster worker nodes","Separating and organizing resources within a cluster"], correct:3, explain:"Namespaces partition a cluster, helping isolate and organize workloads and access.", reward:"Orchestration Sense" },
  { id:"cloud-devops-068", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why limit which branches can trigger a production deployment?", options:["To give the branches much nicer names","To deliberately slow down the builds","To prevent unreviewed or untrusted code from auto-deploying","To end up using much more disk space"], correct:2, explain:"Restricting deploy triggers ensures only approved, reviewed code reaches production.", reward:"Pipeline Sense" },
  { id:"cloud-devops-069", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does a '.gitignore' file help prevent?", options:["Making the commits run much faster","Accidentally committing files like secrets or build artifacts","Producing nicer terminal output colors","Making the repos bigger on purpose"], correct:1, explain:"A .gitignore tells Git which files to skip, helping keep secrets and junk out of the repo.", reward:"Version Control" },
  { id:"cloud-devops-070", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why rotate secrets periodically?", options:["To limit how long a leaked secret stays useful","To deliberately slow the systems","To give secrets much nicer names","To end up using more storage"], correct:0, explain:"Regular rotation shortens the window an exposed secret can be abused.", reward:"Secret Safety" },
  { id:"cloud-devops-071", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why store infrastructure-as-code in version control?", options:["To give files much nicer names","To deliberately slow down deploys","To track changes, review them, and roll back if needed","To end up using more disk space"], correct:2, explain:"Versioned IaC gives history, review, and rollback for infrastructure changes.", reward:"IaC Sense" },
  { id:"cloud-devops-072", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a 'metric' in monitoring?", options:["A scheduled backup of all the data","A dashboard color theme setting","A stored secret account password","A measured value over time, like CPU usage or error rate"], correct:3, explain:"Metrics are numeric measurements tracked over time to understand system behavior.", reward:"Monitoring Focus" },
  { id:"cloud-devops-073", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why set a sensible log retention period?", options:["To keep logs long enough for investigations while managing storage cost","To delete all of the stored logs instantly","To never keep any of the logs at all","To deliberately slow the whole system down"], correct:0, explain:"Retention balances having logs available for investigation against storage cost and limits.", reward:"Log Sense" },
  { id:"cloud-devops-074", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why avoid printing all environment variables in debug output?", options:["Printing them just looks messy","They may contain secrets that would then be exposed","Doing so is a little bit slower","It uses up a bit more memory"], correct:1, explain:"Dumping env vars can leak secrets into logs or screens, so avoid printing them.", reward:"Config Sense" },
  { id:"cloud-devops-075", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why review cloud permissions periodically?", options:["Creating some much nicer dashboards","To deliberately slow down all logins","To end up using much more storage space","Unused or excessive permissions accumulate and should be removed"], correct:3, explain:"Regular reviews catch permission creep, removing access that is no longer needed.", reward:"Access Control" },
  { id:"cloud-devops-076", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why use a staging environment before production?", options:["To design some much nicer company logos","To deliberately slow down the releases","To test changes in a production-like setting before going live","To end up using much more disk space"], correct:2, explain:"Staging mirrors production so changes can be validated safely before real release.", reward:"Deploy Safety" },
  { id:"cloud-devops-077", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why automate rollbacks where possible?", options:["Mainly just for some simple decoration","Fast, reliable recovery reduces downtime when a release fails","To deliberately slow down the deploys","To end up using much more disk space"], correct:1, explain:"Automated rollback shortens recovery time and reduces human error during incidents.", reward:"Rollback Sense" },
  { id:"cloud-devops-078", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why scan images regularly, not just once?", options:["New vulnerabilities are discovered over time in previously clean images","Container images randomly change their colors","To deliberately slow down all image pulls","To give all the images much nicer names"], correct:0, explain:"Vulnerabilities are found continually, so periodic rescans catch newly disclosed issues.", reward:"Image Safety" },
  { id:"cloud-devops-079", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why use a private registry for internal images?", options:["To give images much nicer names","To deliberately slow down pulls","To keep proprietary images from being publicly accessible","To end up using more storage space"], correct:2, explain:"A private registry restricts access so internal images aren't exposed publicly.", reward:"Registry Sense" },
  { id:"cloud-devops-080", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why give developers less access in production than in development?", options:["Giving all the user roles much nicer names","To deliberately slow down all of the work","To end up using much more storage space","Production is sensitive, so tighter access reduces risk to live systems"], correct:3, explain:"Limiting production access protects the live system while developers work freely in dev.", reward:"Environment Sense" },
  { id:"cloud-devops-081", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Which cloud service model provides ready-to-use applications over the web?", options:["Software as a Service (SaaS)","An external hard drive","A home internet router","A small USB memory stick"], correct:0, explain:"SaaS delivers complete applications over the internet, managed by the provider.", reward:"Cloud Basics" },
  { id:"cloud-devops-082", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Shared responsibility mainly clarifies what?", options:["Who exactly designs the company's main logos","Which security tasks belong to the provider and which to the customer","How fast the office internet connection runs","What color the cloud servers are painted"], correct:1, explain:"It defines the split of security duties between the cloud provider and the customer.", reward:"Responsibility Sense" },
  { id:"cloud-devops-083", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why avoid sharing one cloud login among several people?", options:["Sharing logins is a bit slower","Sharing a login simply looks bad","Shared logins use more storage","You lose accountability and can't tell who did what"], correct:3, explain:"Shared accounts erase individual accountability and make auditing actions impossible.", reward:"Access Control" },
  { id:"cloud-devops-084", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Before making a storage bucket public, you should...?", options:["Just go right ahead and do it immediately right now","Add quite a few more files into it first","Confirm it contains no sensitive data and that public access is truly intended","Simply rename the whole storage bucket first"], correct:2, explain:"Public access can expose data, so verify nothing sensitive is inside and that it is intentional.", reward:"Storage Sense" },
  { id:"cloud-devops-085", tier:"Beginner", topic:"Cloud & DevOps", prompt:"How do containers differ from full virtual machines?", options:["They are generally much heavier to run","They share the host OS kernel and are lighter weight","They need no software installed at all","They cannot run any apps at all"], correct:1, explain:"Containers share the host kernel, making them lighter and faster to start than full VMs.", reward:"Container Basics" },
  { id:"cloud-devops-086", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does 'docker pull' do?", options:["Downloads an image from a registry","Deletes a container","Encrypts a disk","Sends email"], correct:0, explain:"docker pull downloads a container image from a registry to your machine.", reward:"Container Basics" },
  { id:"cloud-devops-087", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a Kubernetes 'cluster'?", options:["A single standalone laptop computer device","A magnetic backup tape cartridge in a drawer","A set of machines running and managed together to host containers","A stored list of account passwords"], correct:2, explain:"A cluster is a group of machines (nodes) that Kubernetes manages to run containerized workloads.", reward:"Orchestration Sense" },
  { id:"cloud-devops-088", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does 'CD' (continuous delivery or deployment) focus on?", options:["Cooling down the busy cloud servers","Editing and retouching photo files","Designing brand-new company logos","Getting validated changes released to environments reliably"], correct:3, explain:"CD automates delivering tested changes to environments in a reliable, repeatable way.", reward:"Pipeline Sense" },
  { id:"cloud-devops-089", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a Git 'branch'?", options:["A separate line of development you can work on without affecting main","A physical branch part of an actual tree outside","A metal rack that holds many servers","A secret password used for one account"], correct:0, explain:"A branch lets you develop changes in isolation before merging them back to the main line.", reward:"Version Control" },
  { id:"cloud-devops-090", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Where should production secrets ideally be stored?", options:["In the application code","In a dedicated secrets manager or vault","In a public repository","In an email"], correct:1, explain:"A secrets manager or vault stores secrets securely with access control, unlike code or email.", reward:"Secret Safety" },
  { id:"cloud-devops-091", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Which kind of tool is used for infrastructure as code?", options:["Photo editing software applications","Email reading client software applications","Music playback software media applications","Configuration tools that provision resources from definition files"], correct:3, explain:"IaC tools read definition files and create the described cloud resources automatically.", reward:"IaC Sense" },
  { id:"cloud-devops-092", tier:"Beginner", topic:"Cloud & DevOps", prompt:"A monitoring 'dashboard' is used to...?", options:["Store all the account passwords","Cool down the computer's main CPU","Visualize system health and key metrics at a glance","Encrypt all of the stored data"], correct:2, explain:"Dashboards display metrics and status so teams can see system health quickly.", reward:"Monitoring Focus" },
  { id:"cloud-devops-093", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Which is a good practice for sensitive data in logs?", options:["Log absolutely everything in full detail","Avoid logging secrets and personal data, or mask them","Log all of the passwords twice","Email the logs out to everyone"], correct:1, explain:"Sensitive values should be masked or omitted from logs to prevent leaks.", reward:"Log Sense" },
  { id:"cloud-devops-094", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Environment variables are typically set where?", options:["In the runtime environment or configuration, not hard-coded in the app","Written down on a printed sheet of paper","Stored inside the computer's monitor","Stored inside the keyboard hardware itself"], correct:0, explain:"They are provided by the environment or config at runtime, keeping settings out of the code.", reward:"Config Sense" },
  { id:"cloud-devops-095", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Giving a service account read-only access when it only reads data follows which principle?", options:["Maximum access","No access","Least privilege","Shared access"], correct:2, explain:"Granting only read access when that is all that is needed is least privilege.", reward:"Access Control" },
  { id:"cloud-devops-096", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why test changes before deploying to production?", options:["To make the code look nicer","To deliberately slow things down","To end up using more disk space","To catch problems before they affect real users"], correct:3, explain:"Testing first finds bugs before they reach and impact live users.", reward:"Deploy Safety" },
  { id:"cloud-devops-097", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why take a backup before a risky deployment?", options:["So you can restore data if the deployment goes wrong","Ending up using more disk space","To produce some nicer logs","To deliberately slow things down"], correct:0, explain:"A pre-deployment backup lets you recover data if the change causes problems.", reward:"Rollback Sense" },
  { id:"cloud-devops-098", tier:"Beginner", topic:"Cloud & DevOps", prompt:"If image scanning finds a critical vulnerability, a good response is to...?", options:["Just deploy it anyway as it is","Update or rebuild the image to fix it before deploying","Simply ignore the scan finding","Just rename the container image file"], correct:1, explain:"Critical findings should be fixed by patching or rebuilding before the image is deployed.", reward:"Image Safety" },
  { id:"cloud-devops-099", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why might you sign container images in a registry?", options:["To give the images much nicer names","To deliberately slow down all pulls","To end up using much more storage space","To prove an image is authentic and has not been tampered with"], correct:3, explain:"Signing lets consumers verify an image's authenticity and integrity before running it.", reward:"Registry Sense" },
  { id:"cloud-devops-100", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Which environment should be the most carefully protected?", options:["The main development environment","A temporary testing sandbox setup","Production, because real users and data depend on it","A throwaway scratch virtual machine"], correct:2, explain:"Production runs the live service with real users and data, so it needs the strongest protection.", reward:"Environment Sense" },
  { id:"cloud-devops-201", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a cloud tenant?", options:["An isolated cloud environment or account area used by an organization","A local USB drive","A firewall cable","A browser bookmark"], correct:0, explain:"A tenant is an organization's cloud space where identities, resources, and policies are managed.", reward:"Cloud Basics" },
  { id:"cloud-devops-202", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should cloud tenants have strong admin protection?", options:["Tenant admins cannot change anything","Tenant admins can control identities, resources, policies, and security settings","Admin protection prevents all billing","Cloud tenants do not use accounts"], correct:1, explain:"Tenant admin compromise can affect the whole cloud environment.", reward:"Privileged Cloud" },
  { id:"cloud-devops-203", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a cloud subscription or account commonly used for?", options:["Only storing passwords locally","Only changing monitor brightness","Grouping cloud resources, billing, and access management","Replacing source control"], correct:2, explain:"Cloud accounts or subscriptions help organize resources and permissions.", reward:"Cloud Basics" },
  { id:"cloud-devops-204", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should unused cloud resources be removed?", options:["Unused resources are always free","Unused resources cannot be attacked","Unused resources replace backups","They may create cost, exposure, or unmanaged risk"], correct:3, explain:"Old resources can become forgotten attack surface or cost waste.", reward:"Cloud Hygiene" },
  { id:"cloud-devops-205", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is cloud resource tagging?", options:["Adding labels or metadata to resources for ownership, cost, environment, or purpose","Encrypting every cloud object","Deleting cloud logs","Opening a firewall port"], correct:0, explain:"Tags help organize, manage, and investigate cloud resources.", reward:"Cloud Hygiene" },
  { id:"cloud-devops-206", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why are owner tags useful?", options:["They make resources public","They help identify who is responsible for a resource","They disable alerts","They replace IAM"], correct:1, explain:"Owner tags help teams contact the right person during review or incidents.", reward:"Cloud Hygiene" },
  { id:"cloud-devops-207", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why are environment tags useful?", options:["They prevent all attacks","They delete old resources","They help distinguish production, staging, testing, and development resources","They create access keys"], correct:2, explain:"Environment context helps judge risk and expected behavior.", reward:"Cloud Context" },
  { id:"cloud-devops-208", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should production resources be clearly identified?", options:["Production resources are never important","Production resources cannot be changed","Production resources do not need monitoring","They usually have higher business impact and need stronger controls"], correct:3, explain:"Production systems often handle real users, data, or operations.", reward:"Cloud Context" },
  { id:"cloud-devops-209", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is cloud asset inventory?", options:["A record of cloud resources, owners, environments, and important details","A list of keyboard shortcuts","A malware signature only","A local browser cache"], correct:0, explain:"Cloud inventory helps teams know what exists and what must be secured.", reward:"Cloud Inventory" },
  { id:"cloud-devops-210", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why is cloud inventory difficult?", options:["Cloud resources never change","Cloud environments can change quickly through automation and self-service","Cloud resources cannot be listed","Only physical servers need inventory"], correct:1, explain:"Cloud speed and automation make inventory a continuous task.", reward:"Cloud Inventory" },
  { id:"cloud-devops-211", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a cloud region?", options:["A password policy","A backup file","A geographic area where cloud resources can be hosted","A container image tag"], correct:2, explain:"Regions affect data location, latency, availability, and compliance.", reward:"Cloud Context" },
  { id:"cloud-devops-212", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should unexpected cloud regions be reviewed?", options:["Regions cannot affect cost","Unexpected regions are always safer","Regions replace logging","They may indicate mistakes, shadow IT, or suspicious activity"], correct:3, explain:"Resources in unexpected regions may create risk or cost.", reward:"Cloud Context" },
  { id:"cloud-devops-213", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is cloud availability zone?", options:["A separate location within a cloud region used for resilience","A user password setting","A code review comment","A phishing filter"], correct:0, explain:"Availability zones help design systems that survive local failures.", reward:"Cloud Resilience" },
  { id:"cloud-devops-214", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why use multiple availability zones?", options:["To make systems harder to patch","To improve resilience if one zone has problems","To disable logging","To make all data public"], correct:1, explain:"Multiple zones can reduce downtime from localized failures.", reward:"Cloud Resilience" },
  { id:"cloud-devops-215", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is autoscaling?", options:["Manually deleting servers","Changing passwords every hour","Automatically adjusting resources based on demand","Turning off all monitoring"], correct:2, explain:"Autoscaling helps match capacity to workload needs.", reward:"Cloud Operations" },
  { id:"cloud-devops-216", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why can autoscaling create security or cost concerns?", options:["Autoscaling prevents all abuse","Autoscaling cannot change resources","Autoscaling replaces IAM","Misconfiguration or abuse may create many resources or high cost"], correct:3, explain:"Autoscaling must be controlled and monitored.", reward:"Cloud Cost Sense" },
  { id:"cloud-devops-217", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is serverless computing?", options:["Running code using managed cloud services without managing servers directly","Running only physical servers","Deleting all compute resources","Using no code at all"], correct:0, explain:"Serverless lets teams run functions or workloads while the provider manages much of the infrastructure.", reward:"Serverless Basics" },
  { id:"cloud-devops-218", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a cloud function?", options:["A firewall rule only","Small code executed by a managed serverless platform in response to events or requests","A local text file","A password reset token"], correct:1, explain:"Functions are common serverless compute units.", reward:"Serverless Basics" },
  { id:"cloud-devops-219", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should serverless permissions be limited?", options:["Serverless code cannot access data","Serverless functions are always safe","A compromised or buggy function can abuse its assigned permissions","Serverless removes all IAM"], correct:2, explain:"Serverless workloads need least privilege like any other workload.", reward:"Serverless Security" },
  { id:"cloud-devops-220", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should serverless logs be enabled?", options:["Serverless cannot be monitored","Logs make functions public","Logs prevent all vulnerabilities","They help investigate execution, errors, and suspicious activity"], correct:3, explain:"Serverless logs provide visibility into function behavior.", reward:"Serverless Security" },
  { id:"cloud-devops-221", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a cloud database service?", options:["A managed database provided by a cloud platform","A paper notebook","A local keyboard driver","A phishing template"], correct:0, explain:"Cloud databases reduce infrastructure management but still need secure configuration.", reward:"Database Basics" },
  { id:"cloud-devops-222", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should cloud databases avoid public exposure when possible?", options:["Databases cannot contain sensitive data","Public exposure increases risk of scanning, guessing, and exploitation","Public databases are automatically encrypted","Public exposure prevents all attacks"], correct:1, explain:"Databases should generally be reachable only by trusted services or networks.", reward:"Database Security" },
  { id:"cloud-devops-223", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is database encryption at rest?", options:["Deleting old rows","Compressing database tables","Protecting stored database data with encryption","Opening the database to the internet"], correct:2, explain:"Encryption at rest helps protect stored data if storage is accessed improperly.", reward:"Database Security" },
  { id:"cloud-devops-224", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should database backups be protected?", options:["Backups never contain real data","Backups cannot be copied","Backups replace access control","They may contain sensitive production data"], correct:3, explain:"Backups need the same level of care as the original data.", reward:"Backup Security" },
  { id:"cloud-devops-225", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is DevSecOps?", options:["Integrating security into DevOps practices, automation, and culture","Removing security from deployment","Only doing security after incidents","Deleting all pipelines"], correct:0, explain:"DevSecOps builds security into development and operations workflows.", reward:"DevSecOps" },
  { id:"cloud-devops-226", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does shift-left security mean?", options:["Moving all servers left in a diagram","Finding and fixing security issues earlier in development","Waiting until production to test security","Removing code review"], correct:1, explain:"Shift-left security catches issues before they become expensive production problems.", reward:"Shift Left" },
  { id:"cloud-devops-227", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Which is an example of shift-left security?", options:["Ignoring code until after a breach","Only checking logs after deployment","Scanning code or dependencies before merge","Turning off pipeline checks"], correct:2, explain:"Pre-merge checks help catch risk early.", reward:"Shift Left" },
  { id:"cloud-devops-228", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should security checks be automated in pipelines?", options:["Automation removes all human judgment","Automation makes all code secure","Automation disables developers","It provides consistent early feedback and reduces repeated manual work"], correct:3, explain:"Automated checks help scale security across frequent changes.", reward:"Pipeline Security" },
  { id:"cloud-devops-229", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is static application security testing?", options:["Analyzing source code or compiled code for potential security issues without running it","Running a production outage test","Deleting dependencies","Changing cloud regions"], correct:0, explain:"SAST can catch insecure patterns early in development.", reward:"AppSec Basics" },
  { id:"cloud-devops-230", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is dynamic application security testing?", options:["Reading source code only","Testing a running application for security issues","Changing repository permissions","Backing up a database"], correct:1, explain:"DAST tests the application while it is running.", reward:"AppSec Basics" },
  { id:"cloud-devops-231", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is dependency scanning?", options:["Scanning monitor cables","Scanning backup tapes","Checking libraries and packages for known vulnerabilities or risks","Scanning only DNS records"], correct:2, explain:"Dependency scanning helps identify vulnerable third-party components.", reward:"Dependency Safety" },
  { id:"cloud-devops-232", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is secret scanning?", options:["Changing passwords randomly","Encrypting the screen","Deleting repository history","Looking for exposed credentials, keys, or tokens in code and files"], correct:3, explain:"Secret scanning helps catch leaked credentials before attackers do.", reward:"Secret Safety" },
  { id:"cloud-devops-233", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should failed pipeline security checks matter?", options:["They may identify issues that should be fixed before deployment","They should always be ignored","They prove the pipeline is broken","They remove all need for review"], correct:0, explain:"Failed checks are useful warnings and should be triaged.", reward:"Pipeline Security" },
  { id:"cloud-devops-234", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a pipeline artifact?", options:["A firewall log only","A file or output produced by a build, test, or deployment process","A local user account","A cloud region"], correct:1, explain:"Artifacts can include binaries, packages, reports, or container images.", reward:"Pipeline Basics" },
  { id:"cloud-devops-235", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should pipeline artifacts be protected?", options:["Artifacts cannot contain code","Artifacts are always harmless","Artifacts may be deployed or downloaded and can affect production systems","Artifacts replace IAM"], correct:2, explain:"Tampered artifacts can introduce malicious or broken software.", reward:"Supply Chain" },
  { id:"cloud-devops-236", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is environment promotion?", options:["Deleting old environments","Changing a branch name only","Turning off tests","Moving software from development to test, staging, and production"], correct:3, explain:"Promotion moves changes through environments with increasing trust and impact.", reward:"Deployment Safety" },
  { id:"cloud-devops-237", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should production deployments be controlled?", options:["Production affects real users, data, and business operations","Production never matters","Production changes cannot fail","Production logs are unnecessary"], correct:0, explain:"Production needs stronger approvals, testing, and rollback planning.", reward:"Deployment Safety" },
  { id:"cloud-devops-238", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a rollback in deployment?", options:["Deleting the source repository","Returning to a previous known-good version after a problem","Making every service public","Creating a new cloud account"], correct:1, explain:"Rollback helps restore service after a bad release.", reward:"Rollback Sense" },
  { id:"cloud-devops-239", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should rollback plans be tested?", options:["Rollback always works automatically","Rollback prevents all bugs","Untested rollback may fail during a real outage","Rollback replaces monitoring"], correct:2, explain:"Tested rollback improves operational resilience.", reward:"Rollback Sense" },
  { id:"cloud-devops-240", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a deployment approval?", options:["A random commit message","A password reset","A monitor setting","A required review or permission before deployment proceeds"], correct:3, explain:"Approvals add accountability before high-impact changes.", reward:"Deployment Safety" },
  { id:"cloud-devops-241", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is blue-green deployment?", options:["Using two environments so traffic can switch from old version to new version","Changing UI colors","Deploying without testing","Deleting the old version first"], correct:0, explain:"Blue-green deployment supports safer release and rollback.", reward:"Deployment Safety" },
  { id:"cloud-devops-242", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is canary deployment?", options:["Deploying to every user at once","Releasing a change to a small group first before wider rollout","Only deploying to backup systems","Disabling monitoring during release"], correct:1, explain:"Canary deployment limits impact while observing behavior.", reward:"Deployment Safety" },
  { id:"cloud-devops-243", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why monitor after deployment?", options:["Monitoring is only needed before deployment","Monitoring prevents all bugs","New versions may introduce errors, security issues, or performance problems","Monitoring deletes failed releases"], correct:2, explain:"Post-deployment monitoring helps catch issues quickly.", reward:"Deployment Safety" },
  { id:"cloud-devops-244", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a feature flag?", options:["A cloud invoice setting","A Kubernetes password","A firewall blocklist","A switch that enables or disables application behavior without redeploying code"], correct:3, explain:"Feature flags support controlled rollout and rollback of features.", reward:"Release Control" },
  { id:"cloud-devops-245", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should feature flags be protected?", options:["They can change application behavior and may expose or hide functionality","They are only decoration","They prevent all bugs","They cannot affect users"], correct:0, explain:"Feature flags can impact business logic and security.", reward:"Release Control" },
  { id:"cloud-devops-246", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is observability?", options:["Deleting logs after deployment","The ability to understand system behavior using logs, metrics, and traces","A password policy","A container image name"], correct:1, explain:"Observability helps teams investigate and operate systems.", reward:"Observability" },
  { id:"cloud-devops-247", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a metric in operations?", options:["A secret key","A firewall cable","A measurable value such as CPU usage, error rate, or request count","A deleted log"], correct:2, explain:"Metrics help show system health and behavior over time.", reward:"Observability" },
  { id:"cloud-devops-248", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is tracing used for?", options:["Deleting application errors","Resetting all sessions","Opening cloud storage","Following a request across services to understand flow and delays"], correct:3, explain:"Tracing is useful in distributed applications and microservices.", reward:"Observability" },
  { id:"cloud-devops-249", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is microservice architecture?", options:["An application design where functionality is split into smaller services","A single password for all apps","A physical server rack","A local-only spreadsheet"], correct:0, explain:"Microservices divide applications into smaller independently managed services.", reward:"Architecture Basics" },
  { id:"cloud-devops-250", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why can microservices increase security complexity?", options:["They remove all network traffic","There are more services, APIs, identities, and communication paths to protect","They prevent all vulnerabilities","They do not use logs"], correct:1, explain:"More services usually means more relationships and attack surface to manage.", reward:"Architecture Basics" },
  { id:"cloud-devops-251", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should service-to-service authentication be used?", options:["Services should prove identity before trusting requests","Internal services are always safe","Authentication disables logging","Service identity is only needed for users"], correct:0, explain:"Service authentication reduces blind trust between components.", reward:"Service Identity" },
  { id:"cloud-devops-252", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is mutual TLS commonly used for?", options:["Deleting secrets","Both sides of a connection authenticate each other using certificates","Changing DNS TTL","Creating a billing report"], correct:1, explain:"mTLS can protect service-to-service communication.", reward:"Service Identity" },
  { id:"cloud-devops-253", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should APIs use authentication and authorization?", options:["APIs cannot expose data","APIs only serve static images","They control who can call APIs and what actions or data are allowed","APIs replace all logs"], correct:2, explain:"APIs often expose business logic and sensitive data.", reward:"API Security" },
  { id:"cloud-devops-254", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is API rate limiting used for?", options:["Making APIs public","Deleting API logs","Replacing authentication","Reducing abuse such as brute force, scraping, or overload"], correct:3, explain:"Rate limits help control automated abuse and resource exhaustion.", reward:"API Security" },
  { id:"cloud-devops-255", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should API keys be scoped?", options:["Limited keys reduce impact if a key is leaked","API keys cannot be leaked","All keys should be admin keys","Scoped keys prevent all bugs"], correct:0, explain:"Scopes reduce the blast radius of credential exposure.", reward:"API Security" },
  { id:"cloud-devops-256", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is a webhook?", options:["A phishing attachment","An HTTP callback used to send event information between systems","A local admin account","A DNS-only record"], correct:1, explain:"Webhooks are common in automation and integrations.", reward:"Automation Security" },
  { id:"cloud-devops-257", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should webhooks be secured?", options:["Webhooks cannot be abused","Webhooks only send harmless data","Attackers may spoof or abuse webhook requests if validation is weak","Webhooks replace authentication"], correct:2, explain:"Webhook receivers should validate source, signatures, and content.", reward:"Automation Security" },
  { id:"cloud-devops-258", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is a webhook secret used for?", options:["Opening all ports","Changing repository names","Deleting old events","Verifying that webhook requests came from a trusted source"], correct:3, explain:"Webhook secrets support request validation.", reward:"Automation Security" },
  { id:"cloud-devops-259", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should automation accounts follow least privilege?", options:["Automation can perform actions quickly at scale if compromised","Automation accounts cannot be compromised","Automation accounts never use credentials","Least privilege prevents all outages"], correct:0, explain:"Automation needs strong limits because mistakes or compromise can spread fast.", reward:"Automation Security" },
  { id:"cloud-devops-260", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why are long-lived automation credentials risky?", options:["They are always encrypted perfectly","If leaked, they may remain useful for a long time","They cannot be used by attackers","They disable cloud logging"], correct:1, explain:"Temporary credentials reduce exposure compared with long-lived keys.", reward:"Automation Security" },
  { id:"cloud-devops-261", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should automation changes be reviewed?", options:["Automation cannot affect production","Automation changes are always safe","Automation can create, delete, expose, or modify resources quickly","Review prevents all mistakes forever"], correct:2, explain:"Automation has scale, so review matters.", reward:"Change Control" },
  { id:"cloud-devops-262", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is drift detection in infrastructure as code?", options:["Detecting when real infrastructure differs from the expected code-defined state","Deleting source control history","Changing branch names","Backing up secrets"], correct:0, explain:"Drift detection finds manual or unexpected changes outside IaC.", reward:"IaC Security" },
  { id:"cloud-devops-263", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why is manual cloud clicking risky when IaC is expected?", options:["Manual changes may create drift and bypass review or policy checks","Manual changes are always more secure","Manual changes prevent all misconfiguration","IaC cannot track resources"], correct:1, explain:"Unreviewed manual changes can weaken control and repeatability.", reward:"IaC Security" },
  { id:"cloud-devops-264", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is an IaC plan?", options:["A final incident report","A DNS zone file","A preview of infrastructure changes before applying them","A container runtime"], correct:2, explain:"Plans help reviewers understand what will change.", reward:"IaC Basics" },
  { id:"cloud-devops-265", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should IaC plans be reviewed?", options:["Plans cannot reveal risk","Plans only show colors","They can reveal public exposure, deletion, permission changes, or cost impact","Plan review replaces monitoring"], correct:2, explain:"Plan review catches risky changes before deployment.", reward:"IaC Security" },
  { id:"cloud-devops-266", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should IaC state files be protected?", options:["They cannot contain sensitive data","State files are only images","State files prevent cloud access","They may contain resource details, outputs, and sometimes secrets"], correct:3, explain:"IaC state can expose sensitive infrastructure information.", reward:"IaC Security" },
  { id:"cloud-devops-267", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is a cloud guardrail?", options:["A policy, control, or automation that prevents or detects risky cloud actions","A physical railing in a data center","A password reset email","A local-only backup"], correct:0, explain:"Guardrails help teams move quickly while staying within safe boundaries.", reward:"Cloud Guardrails" },
  { id:"cloud-devops-268", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is an example of a cloud guardrail?", options:["Allowing all public storage","Blocking public bucket creation unless explicitly approved","Disabling all audit logs","Giving everyone admin access"], correct:1, explain:"Guardrails can prevent common high-risk misconfigurations.", reward:"Cloud Guardrails" },
  { id:"cloud-devops-269", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should guardrails be tested?", options:["Guardrails are always perfect","Testing deletes cloud resources","To confirm they block or detect the expected risky behavior","Guardrails prevent all attacks"], correct:2, explain:"Controls should be validated, not assumed.", reward:"Control Validation" },
  { id:"cloud-devops-270", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should cloud policies avoid being too broad?", options:["Broad policies may block normal work or allow too much access if written poorly","Broad policies are always safer","Broad policies prevent all risk","Broad policies remove the need for IAM"], correct:0, explain:"Policies need balance, clarity, and testing.", reward:"Policy as Code" },
  { id:"cloud-devops-271", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is a managed identity?", options:["A cloud-provided identity for a workload or service without manually handling long-lived secrets","A personal password note","A firewall cable","A static screenshot"], correct:0, explain:"Managed identities reduce secret handling for cloud workloads.", reward:"Workload Identity" },
  { id:"cloud-devops-272", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why are managed identities useful?", options:["They remove all permissions","They can reduce the need to store static credentials in code or configs","They make every workload admin","They disable audit logs"], correct:1, explain:"Managed identities support safer workload authentication.", reward:"Workload Identity" },
  { id:"cloud-devops-273", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should workload identities be monitored?", options:["Workload identities cannot be abused","Workload identities never access data","Unusual use may indicate compromise, misconfiguration, or automation error","Monitoring disables workloads"], correct:2, explain:"Service and workload identity activity is important security telemetry.", reward:"Workload Identity" },
  { id:"cloud-devops-274", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is privilege creep in cloud IAM?", options:["Permissions slowly accumulating beyond what is needed over time","A container memory leak","A DNS cache issue","A backup compression method"], correct:0, explain:"Privilege creep increases risk and should be controlled by reviews.", reward:"IAM Risk" },
  { id:"cloud-devops-275", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should temporary access be preferred for high-risk tasks?", options:["Temporary access is always public","It reduces the time window where powerful permissions exist","Temporary access prevents all mistakes","Temporary access disables logging"], correct:1, explain:"Short-lived access reduces standing privilege.", reward:"Privileged Cloud" },
  { id:"cloud-devops-276", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is just-in-time cloud access?", options:["Permanent admin access for every developer","Temporary access granted only when needed and often with approval","Access with no audit trail","Public access to all resources"], correct:1, explain:"JIT access helps reduce permanent high privilege.", reward:"Privileged Cloud" },
  { id:"cloud-devops-277", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should break-glass accounts be monitored?", options:["They are low-risk accounts","They should be used daily","They provide emergency high privilege and abnormal use matters","They cannot change anything"], correct:2, explain:"Emergency accounts should be protected and closely watched.", reward:"Privileged Cloud" },
  { id:"cloud-devops-278", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is a cloud landing zone?", options:["A prepared cloud environment structure with baseline security, networking, identity, and governance","A local download folder","A single container image","A password manager extension"], correct:0, explain:"Landing zones help organizations start cloud use with safe foundations.", reward:"Cloud Governance" },
  { id:"cloud-devops-279", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why are cloud naming standards useful?", options:["They make resources impossible to attack","They help identify purpose, owner, environment, and organization","They replace IAM","They prevent all outages"], correct:1, explain:"Good names make resources easier to manage and investigate.", reward:"Cloud Hygiene" },
  { id:"cloud-devops-280", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is cloud compliance monitoring?", options:["Deleting cloud audit logs","Creating phishing pages","Checking cloud resources against required rules, standards, or policies","Changing region names"], correct:2, explain:"Compliance monitoring detects violations and drift from expected controls.", reward:"Cloud Governance" },
  { id:"cloud-devops-281", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should cloud findings have owners?", options:["Findings cannot be fixed","Only attackers need owners","Owners make remediation accountable and trackable","Ownership disables alerts"], correct:2, explain:"Without ownership, cloud risks may remain unresolved.", reward:"Cloud Governance" },
  { id:"cloud-devops-282", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is a cloud security posture management tool used for?", options:["Only changing passwords","Only running containers","Only editing code","Finding and tracking cloud misconfigurations and compliance issues"], correct:3, explain:"CSPM tools help identify risky cloud configurations.", reward:"Cloud Posture" },
  { id:"cloud-devops-283", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should CSPM findings be prioritized?", options:["Teams need to focus first on exposed, exploitable, or high-impact risks","All findings always have equal impact","Low-risk findings should always be first","Prioritization removes remediation"], correct:0, explain:"Risk-based prioritization makes cloud security manageable.", reward:"Cloud Posture" },
  { id:"cloud-devops-284", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is cloud workload protection?", options:["Only managing office printers","Protecting compute workloads such as VMs, containers, and serverless functions","Deleting all logs","Replacing source control"], correct:1, explain:"Cloud workload protection focuses on runtime systems and applications.", reward:"Cloud Workloads" },
  { id:"cloud-devops-285", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should runtime cloud behavior be monitored?", options:["Runtime behavior cannot be suspicious","Runtime monitoring prevents all vulnerabilities","It can reveal exploitation, unusual network activity, or compromised workloads","Runtime logs are only for billing"], correct:2, explain:"Runtime visibility helps detect attacks that pass earlier checks.", reward:"Cloud Workloads" },
  { id:"cloud-devops-286", tier:"Advanced", topic:"Cloud & DevOps", prompt:"A CI job from an external pull request can access production secrets. What is the main risk?", options:["Untrusted code may steal secrets or trigger unauthorized deployment paths","External pull requests are always trusted","Production secrets cannot be used","CI jobs cannot run commands"], correct:0, explain:"Untrusted code must not receive sensitive credentials.", reward:"Pipeline Security" },
  { id:"cloud-devops-287", tier:"Advanced", topic:"Cloud & DevOps", prompt:"A cloud role allows all actions on all resources. Why is this dangerous?", options:["It prevents privilege abuse","It creates excessive blast radius if the role is misused or compromised","It disables cloud APIs","It improves least privilege"], correct:1, explain:"Broad wildcard access can turn small compromise into full compromise.", reward:"IAM Risk" },
  { id:"cloud-devops-288", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why should identity, network, and data context be combined for cloud risk?", options:["One context always tells the full story","Context prevents all attacks","Risk depends on who can access what, from where, and what data is exposed","Data context is irrelevant"], correct:2, explain:"Cloud risk is clearer when permissions, exposure, and sensitivity are connected.", reward:"Cloud Risk" },
  { id:"cloud-devops-289", tier:"Advanced", topic:"Cloud & DevOps", prompt:"What is the risk of a public serverless function with high privileges?", options:["Serverless functions cannot access resources","Public functions are always harmless","High privilege prevents abuse","Anyone who can trigger or exploit it may abuse its permissions"], correct:3, explain:"Public trigger plus high privilege creates dangerous exposure.", reward:"Serverless Security" },
  { id:"cloud-devops-290", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why should build provenance matter?", options:["It helps prove where an artifact came from and how it was built","Build provenance deletes vulnerabilities","Build provenance replaces testing","Artifact origin never matters"], correct:0, explain:"Provenance helps defend against tampered build outputs.", reward:"Supply Chain" },
  { id:"cloud-devops-291", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why should deployments use signed artifacts when possible?", options:["Signed artifacts cannot have bugs","Signatures help verify integrity and trusted origin before deployment","Signing disables rollback","Unsigned artifacts are always safe"], correct:1, explain:"Signing reduces the chance of deploying tampered artifacts.", reward:"Supply Chain" },
  { id:"cloud-devops-292", tier:"Advanced", topic:"Cloud & DevOps", prompt:"What is the danger of mutable container tags in production?", options:["Tags cannot change","Tags always improve integrity","The same tag may later point to different image content","Tags prevent image tampering"], correct:2, explain:"Digest pinning provides stronger immutability than tag names alone.", reward:"Container Security" },
  { id:"cloud-devops-293", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why should Kubernetes admission controls be used?", options:["They can enforce policies before workloads are accepted into the cluster","They disable all pods","They replace all RBAC","They prevent all container vulnerabilities"], correct:0, explain:"Admission controls can block risky workload configurations early.", reward:"Kubernetes Security" },
  { id:"cloud-devops-294", tier:"Advanced", topic:"Cloud & DevOps", prompt:"What is the risk of allowing privileged pods in a shared cluster?", options:["Privileged pods cannot affect hosts","Privileged pods may weaken isolation and increase impact across nodes or workloads","Privileged pods are always read-only","Privileged pods remove attacker access"], correct:1, explain:"Privileged pods should be rare, justified, and tightly controlled.", reward:"Kubernetes Security" },
  { id:"cloud-devops-295", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why should cloud detections include control-plane activity?", options:["Control-plane activity cannot affect security","Control-plane logs are only visual","Control-plane actions show creation, deletion, permission changes, and configuration changes","Only network logs matter"], correct:2, explain:"Cloud attacks often happen through APIs and management actions.", reward:"Cloud Logs" },
  { id:"cloud-devops-296", tier:"Advanced", topic:"Cloud & DevOps", prompt:"What is a mature response to repeated public bucket findings?", options:["Ignore them as normal cloud noise","Only tell developers to be careful","Delete all buckets without review","Add guardrails, IaC checks, owner feedback, and monitoring to prevent recurrence"], correct:3, explain:"Repeated findings need systemic fixes, not only one-off cleanup.", reward:"Cloud Governance" },
  { id:"cloud-devops-297", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why should cloud incident response include cost review?", options:["Cost anomalies may reveal abuse such as cryptomining or runaway resource creation","Cost data is never useful","Cost review replaces log review","Attackers cannot create cost"], correct:0, explain:"Billing anomalies can be an incident signal.", reward:"Cloud Cost Sense" },
  { id:"cloud-devops-298", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why should cloud and DevOps security focus on blast radius?", options:["Blast radius prevents all compromise","Blast radius thinking helps limit impact if an identity, workload, pipeline, or resource is compromised","Blast radius means all resources must be public","Blast radius replaces monitoring"], correct:1, explain:"Reducing blast radius makes failures and compromises less damaging.", reward:"Cloud Risk" },
  { id:"cloud-devops-299", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why should DevOps teams treat pipelines as production systems?", options:["Pipelines are low value","Pipelines cannot affect production","Pipelines may build, sign, test, and deploy production code or infrastructure","Pipelines do not need access control"], correct:2, explain:"Pipelines are critical parts of the software supply chain.", reward:"Pipeline Security" },
  { id:"cloud-devops-300", tier:"Advanced", topic:"Cloud & DevOps", prompt:"What is the best long-term goal for Cloud & DevOps security?", options:["Slow every team down permanently","Remove all automation","Trust every cloud default","Make secure behavior the easiest default through automation, guardrails, and visibility"], correct:3, explain:"Good cloud security supports speed while reducing risk by default.", reward:"Cloud Defense Mindset" },
  { id:"cloud-devops-301", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is cloud misconfiguration?", options:["An insecure or incorrect cloud setting that can create risk","A normal password reset","A local keyboard issue","A safe backup restore"], correct:0, explain:"Misconfigurations are one of the most common cloud security problems.", reward:"Cloud Misconfig" },
  { id:"cloud-devops-302", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Which is an example of cloud misconfiguration?", options:["Using MFA for admins","Making a sensitive storage bucket public by mistake","Keeping audit logs enabled","Using least privilege"], correct:1, explain:"Public sensitive storage is a common and serious cloud misconfiguration.", reward:"Cloud Misconfig" },
  { id:"cloud-devops-303", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should cloud permissions be reviewed regularly?", options:["Permissions never change","Reviews delete all users","Old or excessive permissions can create unnecessary risk","Reviews replace logging"], correct:2, explain:"Cloud permissions can grow over time and should match actual need.", reward:"IAM Review" },
  { id:"cloud-devops-304", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is privilege creep?", options:["A firewall rule update","A backup process","A secure deployment method","Permissions slowly increasing beyond what is needed"], correct:3, explain:"Privilege creep creates excessive access and larger blast radius.", reward:"IAM Risk" },
  { id:"cloud-devops-305", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a cloud audit trail?", options:["A record of cloud actions that can be reviewed later","A physical data center path","A local browser bookmark","A container image label"], correct:0, explain:"Audit trails help show who did what, when, and from where.", reward:"Cloud Logs" },
  { id:"cloud-devops-306", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should cloud audit trails be enabled before incidents?", options:["Audit logs prevent all attacks","Logs are needed to investigate activity after something happens","Audit trails replace MFA","Logs make every resource public"], correct:1, explain:"If audit logs are not enabled before an incident, evidence may be missing.", reward:"Cloud Logs" },
  { id:"cloud-devops-307", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a cloud access review?", options:["A firewall backup","A code formatting task","A check that identities still have appropriate cloud permissions","A DNS zone transfer"], correct:2, explain:"Access reviews help remove unnecessary or risky cloud permissions.", reward:"IAM Review" },
  { id:"cloud-devops-308", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should inactive cloud users be disabled or removed?", options:["Inactive users improve security","Inactive users cannot be abused","Inactive users replace service accounts","They may become forgotten access paths"], correct:3, explain:"Stale cloud users increase account takeover and misuse risk.", reward:"Cloud Hygiene" },
  { id:"cloud-devops-309", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a service account?", options:["A non-human identity used by applications, services, or automation","A personal social media account","A browser cookie","A cloud invoice"], correct:0, explain:"Service accounts allow software and automation to access resources.", reward:"Service Identity" },
  { id:"cloud-devops-310", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should service accounts have owners?", options:["Owners make accounts impossible to compromise","Owners help confirm purpose, permissions, and expected behavior","Owners disable all access keys","Owners replace audit logs"], correct:1, explain:"Ownership makes service accounts easier to review and investigate.", reward:"Service Identity" },
  { id:"cloud-devops-311", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a workload identity?", options:["A local user profile","A firewall policy","An identity used by an application or workload to access resources","A physical server label"], correct:2, explain:"Workload identities allow services to authenticate without acting as human users.", reward:"Workload Identity" },
  { id:"cloud-devops-312", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should workload identities follow least privilege?", options:["Workloads cannot be compromised","Workload identities do not use permissions","Least privilege disables monitoring","A compromised workload can abuse whatever permissions it has"], correct:3, explain:"Limiting workload permissions reduces damage from compromise.", reward:"Workload Identity" },
  { id:"cloud-devops-313", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a cloud secret?", options:["A sensitive value such as a password, token, key, or certificate","A public documentation page","A server name only","A dashboard color"], correct:0, explain:"Cloud secrets must be protected from exposure and misuse.", reward:"Secret Safety" },
  { id:"cloud-devops-314", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Where should secrets usually be stored?", options:["In public source code","In a protected secrets manager or secure vault","In screenshots","In plain text chat messages"], correct:1, explain:"Secrets managers help control access, rotation, and auditing.", reward:"Secret Safety" },
  { id:"cloud-devops-315", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should secrets not be printed in pipeline logs?", options:["Logs cannot be searched","Secrets in logs are harmless","Logs may be visible to people or systems that should not access the secrets","Printed secrets rotate automatically"], correct:2, explain:"Secrets exposed in logs may need urgent rotation.", reward:"Pipeline Secrets" },
  { id:"cloud-devops-316", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a safer way for pipelines to use secrets?", options:["Hard-code them into every script","Commit them to the repository","Print them before deployment","Inject them securely at runtime with limited scope"], correct:3, explain:"Runtime secret injection reduces exposure in code and logs.", reward:"Pipeline Secrets" },
  { id:"cloud-devops-317", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a container runtime?", options:["Software that runs containers on a host","A cloud billing account","A password reset form","A source code branch"], correct:0, explain:"Container runtimes start and manage containers.", reward:"Container Basics" },
  { id:"cloud-devops-318", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should container images be kept small and clean?", options:["Large images are always malicious","Smaller images can reduce attack surface and unnecessary packages","Image size prevents all vulnerabilities","Images cannot contain tools"], correct:1, explain:"Fewer packages often means fewer vulnerabilities and less exposed tooling.", reward:"Container Security" },
  { id:"cloud-devops-319", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a container vulnerability scan?", options:["A scan of monitor cables","A scan of passwords only","A check for known vulnerabilities or risks inside container images","A cloud invoice review"], correct:2, explain:"Scanning images helps find vulnerable packages before runtime.", reward:"Container Security" },
  { id:"cloud-devops-320", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should image scan results be reviewed?", options:["Scan results are always useless","Scans prevent all attacks automatically","Vulnerabilities do not matter in images","Teams need to decide what must be fixed before deployment"], correct:3, explain:"Scan results support risk-based remediation.", reward:"Container Security" },
  { id:"cloud-devops-321", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a Kubernetes namespace?", options:["A logical grouping used to separate resources inside a cluster","A cloud password type","A backup region","A firewall vendor"], correct:0, explain:"Namespaces help organize and separate Kubernetes resources.", reward:"Kubernetes Basics" },
  { id:"cloud-devops-322", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why are Kubernetes namespaces useful?", options:["They prevent all attacks","They help separate teams, environments, or applications inside a cluster","They remove the need for RBAC","They make all pods public"], correct:1, explain:"Namespaces help with organization and policy boundaries.", reward:"Kubernetes Basics" },
  { id:"cloud-devops-323", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a Kubernetes secret?", options:["A hidden pod name","A DNS record","An object used to store sensitive values such as tokens or passwords","A container image tag"], correct:2, explain:"Kubernetes secrets need careful access control and encryption.", reward:"Kubernetes Secrets" },
  { id:"cloud-devops-324", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should Kubernetes secrets not be broadly readable?", options:["Secrets are always public","Secrets cannot be abused","Broad read access improves least privilege","They may expose credentials or tokens to unauthorized users or workloads"], correct:3, explain:"Access to secrets should be limited to what actually needs them.", reward:"Kubernetes Secrets" },
  { id:"cloud-devops-325", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is Kubernetes RBAC?", options:["A permission system controlling actions in Kubernetes","A backup compression format","A container image scanner only","A cloud billing report"], correct:0, explain:"RBAC controls who can do what in a Kubernetes cluster.", reward:"Kubernetes Security" },
  { id:"cloud-devops-326", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should Kubernetes admin rights be limited?", options:["Admin rights cannot change anything","Cluster admin access can affect many workloads and secrets","Admin rights disable all logs","Admin rights prevent compromise"], correct:1, explain:"Cluster-level permissions are powerful and should be restricted.", reward:"Kubernetes Security" },
  { id:"cloud-devops-327", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a Kubernetes node?", options:["A user password","A source code branch","A machine that runs workloads in a Kubernetes cluster","A storage bucket policy"], correct:2, explain:"Nodes provide compute resources for pods.", reward:"Kubernetes Basics" },
  { id:"cloud-devops-328", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should Kubernetes nodes be patched?", options:["Nodes cannot have vulnerabilities","Patching nodes disables workloads permanently","Nodes do not run software","Node vulnerabilities can affect workloads and cluster security"], correct:3, explain:"Cluster nodes are still systems that need security maintenance.", reward:"Kubernetes Security" },
  { id:"cloud-devops-329", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is an ingress in Kubernetes?", options:["A way to route external traffic into services in a cluster","A password vault","A backup script","A local desktop setting"], correct:0, explain:"Ingress controls how external requests reach services.", reward:"Kubernetes Network" },
  { id:"cloud-devops-330", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should ingress exposure be reviewed?", options:["Ingress cannot expose services","It may make internal services reachable from outside","Ingress disables authentication","Ingress replaces network policy"], correct:1, explain:"Ingress can create external attack surface.", reward:"Kubernetes Network" },
  { id:"cloud-devops-331", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a container breakout conceptually?", options:["A container safely stopping","A backup restore","Escaping from a container to affect the host or other workloads","A normal image pull"], correct:2, explain:"Container breakout weakens isolation and can increase impact.", reward:"Container Security" },
  { id:"cloud-devops-332", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should privileged containers be rare?", options:["Privileged containers cannot be compromised","Privileged containers are always safer","Privileged containers prevent all malware","They weaken isolation and can increase host-level impact"], correct:3, explain:"Privileged containers should require strong justification.", reward:"Container Security" },
  { id:"cloud-devops-333", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a build artifact?", options:["An output from a build process, such as a package, binary, report, or image","A keyboard shortcut","A user account","A cloud region"], correct:0, explain:"Artifacts are often later tested, stored, signed, or deployed.", reward:"Pipeline Basics" },
  { id:"cloud-devops-334", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should build artifacts be stored securely?", options:["Artifacts cannot be modified","Tampered artifacts may introduce malicious or broken software","Artifacts are always temporary and harmless","Artifacts replace code review"], correct:1, explain:"Artifact integrity matters because artifacts may reach production.", reward:"Supply Chain" },
  { id:"cloud-devops-335", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is code signing?", options:["Writing comments in code","Deleting old commits","Using a cryptographic signature to prove software origin or integrity","Changing file names"], correct:2, explain:"Code signing helps verify software came from a trusted source and was not modified.", reward:"Supply Chain" },
  { id:"cloud-devops-336", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should signing keys be protected?", options:["Signing keys are public by design","Signing keys cannot be stolen","Signing keys prevent all bugs","Stolen signing keys can make malicious software appear trusted"], correct:3, explain:"Signing keys are high-value secrets.", reward:"Supply Chain" },
  { id:"cloud-devops-337", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is dependency confusion?", options:["Tricking systems into installing the wrong package from an unexpected source","A normal dependency update","A secure backup method","A firewall log format"], correct:0, explain:"Dependency confusion abuses package resolution and naming.", reward:"Dependency Safety" },
  { id:"cloud-devops-338", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why are package names important?", options:["Package names cannot be abused","Similar or confusing names can trick users or automation into installing the wrong package","Package names prevent vulnerabilities","Package names replace code review"], correct:1, explain:"Typosquatting and lookalike packages are supply-chain risks.", reward:"Dependency Safety" },
  { id:"cloud-devops-339", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a lockfile in dependency management?", options:["A locked user account","A firewall blocklist","A file recording exact dependency versions for repeatable installs","A cloud audit log"], correct:2, explain:"Lockfiles make builds more predictable.", reward:"Dependency Safety" },
  { id:"cloud-devops-340", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why are repeatable builds useful?", options:["They prevent all security issues","They make dependencies irrelevant","They disable testing","They reduce unexpected changes between environments or build runs"], correct:3, explain:"Repeatability improves trust and troubleshooting.", reward:"Supply Chain" },
  { id:"cloud-devops-341", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a deployment environment?", options:["A place where software runs, such as development, staging, or production","A local keyboard layout","A password policy only","A deleted repository"], correct:0, explain:"Different environments have different levels of risk and control.", reward:"Environment Safety" },
  { id:"cloud-devops-342", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should development and production be separated?", options:["Production should be easier to break","Separation reduces the chance that test mistakes affect real users or sensitive data","Development always needs full production secrets","Separation disables deployment"], correct:1, explain:"Environment separation reduces blast radius.", reward:"Environment Safety" },
  { id:"cloud-devops-343", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is staging environment?", options:["A public storage bucket","A cloud invoice","A pre-production environment used for testing before release","A password manager"], correct:2, explain:"Staging helps validate changes before production.", reward:"Deployment Safety" },
  { id:"cloud-devops-344", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should staging not be trusted like production automatically?", options:["Staging always has better controls","Staging prevents all attacks","Staging has no users","Staging may have weaker controls but still contain sensitive access or data"], correct:3, explain:"Staging can become an attack path if treated carelessly.", reward:"Environment Safety" },
  { id:"cloud-devops-345", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is production data?", options:["Real operational data used by live systems or real users","Fake sample data only","A screenshot of a pipeline","A DNS cache file"], correct:0, explain:"Production data often has higher sensitivity and business impact.", reward:"Data Protection" },
  { id:"cloud-devops-346", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should production data not be copied freely into test environments?", options:["Test environments are always more secure","It may expose real sensitive data in less-protected places","Production data prevents testing","Copying data removes all risk"], correct:1, explain:"Use masked or synthetic data where possible.", reward:"Data Protection" },
  { id:"cloud-devops-347", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is synthetic test data?", options:["Real customer secrets","Cloud provider billing data","Fake data created for testing without exposing real sensitive values","A deleted backup"], correct:2, explain:"Synthetic data supports testing while reducing privacy risk.", reward:"Data Protection" },
  { id:"cloud-devops-348", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why should logs from production systems be protected?", options:["Logs cannot contain sensitive data","Logs should always be public","Logs prevent all attacks","They may contain user data, secrets, errors, or internal details"], correct:3, explain:"Logs can be sensitive and should be access-controlled.", reward:"Log Protection" },
  { id:"cloud-devops-349", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is cloud incident response?", options:["Preparing for and handling security incidents in cloud environments","Deleting all cloud resources","Only checking local laptops","Changing code formatting"], correct:0, explain:"Cloud incident response includes identity, logs, resources, workloads, and data.", reward:"Cloud IR" },
  { id:"cloud-devops-350", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why is cloud incident response different from traditional response?", options:["Cloud incidents never need logs","Cloud uses APIs, identities, managed services, and fast-changing resources","Cloud systems cannot be compromised","Cloud response has no permissions"], correct:1, explain:"Cloud investigations often rely on control-plane logs and identity activity.", reward:"Cloud IR" },
  { id:"cloud-devops-351", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"A cloud user creates a new access key from an unusual location. What should be checked?", options:["Only the username length","User history, source location, MFA, key usage, permissions, and recent activity","Only the dashboard color","Nothing if the key exists"], correct:1, explain:"New key creation can be normal or a sign of credential abuse.", reward:"Cloud IAM Monitoring" },
  { id:"cloud-devops-352", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should newly created cloud keys be monitored?", options:["Keys cannot be used by attackers","New keys always indicate normal activity","They may provide persistent API access after account compromise","Key creation disables logs"], correct:2, explain:"Access keys can allow continued access unless revoked.", reward:"Cloud Secrets" },
  { id:"cloud-devops-353", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"A public database is found in a cloud environment. What is the best first concern?", options:["The database might expose sensitive data or be reachable by attackers","Public databases are always safe","Databases cannot be scanned","Public exposure improves resilience"], correct:0, explain:"Public database exposure can lead to data theft or compromise.", reward:"Database Security" },
  { id:"cloud-devops-354", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What should be reviewed after finding public database exposure?", options:["Only the database icon","Data sensitivity, access logs, authentication, exposure duration, and owner","Only the cloud region name","Only the monthly bill"], correct:1, explain:"Exposure findings need impact and access analysis.", reward:"Database Security" },
  { id:"cloud-devops-355", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should security groups avoid allowing 0.0.0.0/0 to admin ports?", options:["0.0.0.0/0 blocks all attackers","Admin ports should usually not be reachable from the entire internet","Admin ports cannot be attacked","Wide access disables scanning"], correct:1, explain:"Broad internet access to admin ports is a common cloud risk.", reward:"Network Security" },
  { id:"cloud-devops-356", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What does 0.0.0.0/0 usually mean in an allow rule?", options:["Only local host access","No access allowed","Any IPv4 address can connect","Only cloud provider support can connect"], correct:2, explain:"0.0.0.0/0 commonly represents the entire IPv4 internet.", reward:"Network Security" },
  { id:"cloud-devops-357", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should cloud network rules include business justification?", options:["Justification helps determine whether exposure is needed and who owns the risk","Justification prevents all attacks","Network rules cannot affect risk","Justification replaces monitoring"], correct:0, explain:"Documented justification supports review and cleanup.", reward:"Cloud Governance" },
  { id:"cloud-devops-358", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should cloud load balancers be monitored?", options:["They cannot expose services","They sit on important traffic paths and can reveal exposure, errors, or abuse","They only affect billing labels","They prevent all web attacks"], correct:1, explain:"Load balancers are useful sources for traffic and application visibility.", reward:"Network Security" },
  { id:"cloud-devops-359", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is a risky pipeline permission?", options:["Read-only access to test logs","Access only to one test artifact","Permission to deploy to production from unreviewed code","No access to secrets"], correct:2, explain:"Production deployment permission should be tightly controlled.", reward:"Pipeline Security" },
  { id:"cloud-devops-360", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should deployment credentials be separated by environment?", options:["All environments should share one credential","Development credentials should control production","Credential separation is only cosmetic","Compromise of one environment should not grant access to all environments"], correct:3, explain:"Separate credentials reduce blast radius.", reward:"Environment Safety" },
  { id:"cloud-devops-361", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should pipeline jobs run with minimal permissions?", options:["Jobs can be abused if code, dependencies, or runners are compromised","Minimal permissions disable builds","Jobs cannot access resources","All jobs need admin rights"], correct:0, explain:"Pipeline least privilege limits supply-chain impact.", reward:"Pipeline Security" },
  { id:"cloud-devops-362", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is a protected branch?", options:["A branch that cannot contain code","A branch with restrictions such as required review before changes are merged","A deleted repository branch","A branch that disables builds"], correct:1, explain:"Protected branches reduce the chance of unreviewed risky changes.", reward:"Source Control" },
  { id:"cloud-devops-363", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should production deployment usually come from protected branches?", options:["Protected branches are always bug-free","Production does not need review","They enforce review and reduce untrusted change paths","Protected branches disable logs"], correct:2, explain:"Deployment source control rules help protect production.", reward:"Deployment Safety" },
  { id:"cloud-devops-364", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should commit history be reviewed after suspected repository compromise?", options:["Commit history cannot reveal anything","Only current files matter","Commit history prevents compromise","It may show unauthorized changes, secret exposure, or malicious code insertion"], correct:3, explain:"Repository history can contain important investigation evidence.", reward:"Source Control" },
  { id:"cloud-devops-365", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is a malicious dependency update risk?", options:["A package update may introduce malicious code through a trusted dependency path","Updates cannot contain code","Dependencies are always safe","Updates prevent all attacks"], correct:0, explain:"Dependency updates are part of the software supply chain.", reward:"Supply Chain" },
  { id:"cloud-devops-366", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should dependency changes be visible in pull requests?", options:["Dependency changes cannot affect security","Reviewers need to understand new or changed third-party code risk","Pull requests cannot show dependencies","Dependencies replace testing"], correct:1, explain:"Dependency changes may alter application security and behavior.", reward:"Dependency Safety" },
  { id:"cloud-devops-367", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is a transitive dependency?", options:["A direct package installed by the user only","A firewall dependency","A dependency required by another dependency","A cloud region"], correct:2, explain:"Transitive dependencies can still introduce vulnerabilities.", reward:"Dependency Safety" },
  { id:"cloud-devops-368", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why are transitive dependencies security-relevant?", options:["They cannot contain vulnerabilities","They are never included in builds","They prevent malicious packages","Applications may inherit risk from packages they did not directly choose"], correct:3, explain:"Supply-chain risk includes indirect dependencies.", reward:"Dependency Safety" },
  { id:"cloud-devops-369", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should container image provenance be tracked?", options:["It helps know where an image came from and whether it was built by a trusted process","Images cannot be tampered with","Provenance replaces scanning","Image origin never matters"], correct:0, explain:"Provenance supports supply-chain trust.", reward:"Container Security" },
  { id:"cloud-devops-370", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is a container image digest?", options:["A user password","A content-based identifier for a specific image version","A cloud invoice ID","A Kubernetes namespace"], correct:1, explain:"Digests identify exact image contents more reliably than mutable tags.", reward:"Container Security" },
  { id:"cloud-devops-371", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why is using image digests safer than only using tags?", options:["Tags cannot change","Digests are only decorative","Digests point to specific image content while tags may change","Digests disable vulnerabilities"], correct:2, explain:"Digest pinning improves deployment integrity.", reward:"Container Security" },
  { id:"cloud-devops-372", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is runtime container monitoring?", options:["Only scanning source code","Only checking billing","Only reviewing pull requests","Watching running containers for suspicious behavior or policy violations"], correct:3, explain:"Runtime monitoring detects behavior after deployment.", reward:"Container Security" },
  { id:"cloud-devops-373", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should Kubernetes API access be restricted?", options:["The Kubernetes API can control workloads, secrets, and cluster configuration","The API cannot change anything","Restricting API access disables pods","The API is only for billing"], correct:0, explain:"Kubernetes API permissions are powerful and sensitive.", reward:"Kubernetes Security" },
  { id:"cloud-devops-374", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is Kubernetes admission control?", options:["A billing approval","A mechanism that evaluates requests before resources are created or changed","A pod log type","A password reset"], correct:1, explain:"Admission controls can enforce security policies at deployment time.", reward:"Kubernetes Security" },
  { id:"cloud-devops-375", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What can admission controls help block?", options:["All network traffic","All user logins","Privileged pods, unsafe images, missing labels, or policy violations","All backups"], correct:2, explain:"Admission controls enforce cluster rules before risky workloads run.", reward:"Kubernetes Security" },
  { id:"cloud-devops-376", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should Kubernetes workloads define security contexts?", options:["Security contexts cannot affect pods","Security contexts replace all IAM","Security contexts disable logging","They control settings such as user, privilege, and filesystem access"], correct:3, explain:"Security contexts help enforce least privilege for containers.", reward:"Kubernetes Security" },
  { id:"cloud-devops-377", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is a read-only root filesystem in containers?", options:["A setting that prevents the container's root filesystem from being written to","A backup-only storage disk","A public cloud bucket","A DNS policy"], correct:0, explain:"Read-only filesystems can reduce persistence and tampering options.", reward:"Container Security" },
  { id:"cloud-devops-378", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should containers drop unnecessary Linux capabilities?", options:["All capabilities are required for every app","Fewer capabilities reduce what a compromised container can do","Capabilities prevent all attacks","Dropping capabilities disables the application always"], correct:1, explain:"Capability reduction supports least privilege.", reward:"Container Security" },
  { id:"cloud-devops-379", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is Kubernetes network segmentation used for?", options:["Changing pod names","Deleting namespaces","Limiting which pods or services can communicate","Disabling all traffic permanently"], correct:2, explain:"Segmentation reduces lateral movement inside clusters.", reward:"Kubernetes Network" },
  { id:"cloud-devops-380", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should namespaces not be treated as full security boundaries by themselves?", options:["Namespaces always isolate everything perfectly","Namespaces cannot organize resources","Namespaces replace RBAC","Extra controls such as RBAC and network policies are still needed"], correct:3, explain:"Namespaces help organization but are not complete isolation alone.", reward:"Kubernetes Security" },
  { id:"cloud-devops-381", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should cloud backup policies include deletion protection?", options:["Attackers or mistakes may delete backups needed for recovery","Backups cannot be deleted","Deletion protection prevents all incidents","Backups are never important"], correct:0, explain:"Deletion protection supports resilience against mistakes and malicious activity.", reward:"Backup Security" },
  { id:"cloud-devops-382", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is immutable backup storage?", options:["Storage that anyone can edit","Backup storage designed to prevent modification or deletion for a defined period","A public storage bucket","A container image tag"], correct:1, explain:"Immutability helps preserve recovery copies.", reward:"Backup Security" },
  { id:"cloud-devops-383", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should backup restore permissions be controlled?", options:["Restores cannot affect systems","Anyone should restore production data anywhere","Restores may expose or overwrite sensitive production data","Restore permissions prevent all attacks"], correct:2, explain:"Restore operations can affect confidentiality and availability.", reward:"Backup Security" },
  { id:"cloud-devops-384", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should cloud recovery be tested?", options:["Recovery always works automatically","Recovery tests are only paperwork","Recovery replaces monitoring","Cloud dependencies, permissions, and data paths may fail during real incidents"], correct:3, explain:"Recovery must be proven before a crisis.", reward:"Cloud Resilience" },
  { id:"cloud-devops-385", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why should incident responders know cloud API actions?", options:["Cloud incidents often involve API calls for identity, storage, compute, and configuration changes","Cloud APIs are never logged","API actions cannot affect resources","Only endpoint logs matter"], correct:0, explain:"Cloud control-plane activity is central to cloud investigations.", reward:"Cloud IR" },
  { id:"cloud-devops-386", tier:"Advanced", topic:"Cloud & DevOps", prompt:"A workload identity has permission to read all storage buckets. What is the main risk?", options:["A compromised workload may access far more data than it needs","Workload identities cannot be compromised","Read permissions never matter","Storage buckets cannot contain sensitive data"], correct:0, explain:"Excessive read permissions can create major data exposure risk.", reward:"Cloud Risk" },
  { id:"cloud-devops-387", tier:"Advanced", topic:"Cloud & DevOps", prompt:"A production pipeline uses the same credentials as development. Why is this dangerous?", options:["Shared credentials are always safer","Development compromise may lead directly to production access","Production credentials cannot be used","Credential sharing prevents all attacks"], correct:1, explain:"Environment separation should include credentials and permissions.", reward:"Environment Safety" },
  { id:"cloud-devops-388", tier:"Advanced", topic:"Cloud & DevOps", prompt:"A container image passes vulnerability scan but runs suspicious commands at runtime. What lesson applies?", options:["Image scanning replaces runtime monitoring","Runtime behavior does not matter","Build-time scanning and runtime monitoring both matter","The container must be safe because scanning passed"], correct:2, explain:"Static checks are useful, but runtime behavior can reveal active abuse.", reward:"Container Security" },
  { id:"cloud-devops-389", tier:"Advanced", topic:"Cloud & DevOps", prompt:"A Kubernetes service account can list secrets across all namespaces. What should defenders do?", options:["Ignore it because service accounts are safe","Make all secrets public","Disable all pods","Reduce permissions, review usage, and investigate possible exposure"], correct:3, explain:"Broad secret access is high risk and should be corrected.", reward:"Kubernetes Security" },
  { id:"cloud-devops-390", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why should IaC security checks run before merge, not only after deployment?", options:["Earlier checks prevent risky changes from reaching environments and reduce rework","Post-deployment checks are always enough","IaC cannot create real resources","Pre-merge checks disable automation"], correct:0, explain:"Catching issues before merge is safer and cheaper than fixing production.", reward:"Shift Left" },
  { id:"cloud-devops-391", tier:"Advanced", topic:"Cloud & DevOps", prompt:"A cloud role is rarely used but highly privileged. Why is that concerning?", options:["Rare use means it is automatically safe","It may be forgotten standing privilege with high blast radius if compromised","Rare roles cannot be abused","Privileged roles do not need monitoring"], correct:1, explain:"Unused or rare high privilege should be reviewed and possibly removed.", reward:"IAM Risk" },
  { id:"cloud-devops-392", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why should cloud security findings be connected to business context?", options:["Business context is never useful","All cloud findings are equal","It helps prioritize based on data sensitivity, exposure, owner, and impact","Context prevents remediation"], correct:2, explain:"Business context helps focus on risks that matter most.", reward:"Cloud Risk" },
  { id:"cloud-devops-393", tier:"Advanced", topic:"Cloud & DevOps", prompt:"A CI runner is self-hosted and reachable by many projects. What is a key concern?", options:["Self-hosted runners cannot run code","Runners do not need isolation","All projects are always trusted","One compromised project or job may affect shared runner resources or secrets"], correct:3, explain:"Shared runners need strong isolation and secret handling.", reward:"Pipeline Security" },
  { id:"cloud-devops-394", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why should cloud logs be sent to a separate protected account or workspace?", options:["It helps preserve evidence if the main environment is compromised","It makes logs less useful","It gives attackers easier access","It disables detection"], correct:0, explain:"Separate protected logging reduces tampering risk.", reward:"Cloud Logs" },
  { id:"cloud-devops-395", tier:"Advanced", topic:"Cloud & DevOps", prompt:"What is a mature way to reduce cloud blast radius?", options:["Give all workloads the same admin role","Use segmentation, scoped IAM, environment separation, and short-lived credentials","Disable audit logging","Put all resources in one public network"], correct:1, explain:"Blast radius is reduced by limiting access and separating environments.", reward:"Cloud Risk" },
  { id:"cloud-devops-396", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why should DevOps teams avoid treating security as a final gate only?", options:["Final gates are the only useful security","Late security checks always prevent incidents","Security built throughout the workflow catches issues earlier and creates better defaults","Security should never be automated"], correct:2, explain:"Security works best when integrated across design, code, build, deploy, and run.", reward:"DevSecOps" },
  { id:"cloud-devops-397", tier:"Advanced", topic:"Cloud & DevOps", prompt:"A public API, weak rate limits, and broad cloud permissions combine into one path. What concept is this?", options:["A harmless deployment","A single isolated bug only","A backup strategy","An attack path created by multiple connected weaknesses"], correct:3, explain:"Attack paths often combine application, identity, and cloud misconfigurations.", reward:"Attack Path" },
  { id:"cloud-devops-398", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why should cloud incident response include identity token and session review?", options:["Attackers may keep access through tokens or sessions even after a password reset","Tokens are never used in cloud","Session review replaces log review","Tokens prevent compromise"], correct:0, explain:"Identity response often requires revoking sessions and reviewing token use.", reward:"Cloud IR" },
  { id:"cloud-devops-399", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why should DevOps security metrics include remediation time?", options:["It shows how long known risks remain open before they are fixed","Remediation time prevents all vulnerabilities","Metrics replace actual fixes","Slow remediation is always better"], correct:1, explain:"Time-to-remediate helps measure operational security maturity.", reward:"Quality Metrics" },
  { id:"cloud-devops-400", tier:"Advanced", topic:"Cloud & DevOps", prompt:"What is the strongest long-term Cloud & DevOps security principle?", options:["Move fast by giving everyone admin access","Disable logs to reduce noise","Make secure defaults, least privilege, automation, visibility, and recovery part of normal delivery","Only check security after incidents"], correct:2, explain:"Good cloud and DevOps security makes safe delivery the normal path.", reward:"Cloud Defense Mindset" },
  { id:"cloud-devops-401", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does IaaS (infrastructure as a service) provide?", options:["Compute, storage, and networking that you manage yourself","Ready-made apps with nothing to manage","Only a place to keep office documents","A physical server you own in your building"], correct:0, explain:"IaaS gives raw building blocks like virtual machines and storage that the customer configures.", reward:"Cloud Basics" },
  { id:"cloud-devops-402", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does PaaS mainly offer developers?", options:["Full control of the underlying hardware","A managed platform to build and run apps","Only raw virtual machines to configure yourself","A desktop office suite for end users"], correct:1, explain:"PaaS handles the servers and runtime so developers focus on their application code.", reward:"Cloud Basics" },
  { id:"cloud-devops-403", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a SaaS product?", options:["A bare server you must patch yourself","A toolkit for building your own platform","A ready-to-use application delivered over the web","A local program installed from a disc"], correct:2, explain:"SaaS delivers complete software over the internet, fully managed by the provider.", reward:"Cloud Basics" },
  { id:"cloud-devops-404", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does a cloud region represent?", options:["A backup file format used for archives","A type of network firewall rule","A billing plan made for small accounts","A geographic area where cloud resources are hosted"], correct:3, explain:"Regions are physical locations; choosing one affects latency, cost, and data residency.", reward:"Cloud Basics" },
  { id:"cloud-devops-405", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why deploy across multiple availability zones?", options:["To keep running if one data center fails","So the app loads with brighter colors","To avoid ever needing any backups","To reduce the number of user accounts"], correct:0, explain:"Spreading across zones adds resilience so a single facility failure does not cause an outage.", reward:"Resilience Sense" },
  { id:"cloud-devops-406", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does autoscaling do?", options:["Locks capacity permanently at one size","Adds or removes capacity as demand changes","Encrypts every request automatically","Deletes idle user accounts each night"], correct:1, explain:"Autoscaling matches resources to load, improving cost and handling traffic spikes.", reward:"Scaling Sense" },
  { id:"cloud-devops-407", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does a load balancer do?", options:["Keeps the only copy of user data","Signs software releases for developers","Spreads incoming traffic across several servers","Blocks all traffic from the internet"], correct:2, explain:"A load balancer distributes requests so no single server is overwhelmed.", reward:"Traffic Sense" },
  { id:"cloud-devops-408", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is object storage (a bucket) good for?", options:["Running a relational database engine","Serving as the computer's main memory","Acting as a cable between server racks","Holding files and large unstructured data"], correct:3, explain:"Object storage suits files, media, and backups rather than transactional databases.", reward:"Storage Sense" },
  { id:"cloud-devops-409", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why is a publicly readable storage bucket risky?", options:["Anyone on the internet may read its contents","It always slows the whole network down","Public buckets cannot store any files","It automatically deletes its own data"], correct:0, explain:"Misconfigured public buckets are a common cause of accidental data exposure.", reward:"Storage Sense" },
  { id:"cloud-devops-410", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does encryption at rest protect?", options:["Data only while it travels the network","Stored data if the disk or storage is accessed","How fast files can be downloaded","The number of users who can log in"], correct:1, explain:"Encryption at rest keeps stored data unreadable if the underlying media is exposed.", reward:"Storage Sense" },
  { id:"cloud-devops-411", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does encryption in transit protect?", options:["Files only while sitting on disk","The brightness of the dashboard","Data while it moves between systems","The total number of stored objects"], correct:2, explain:"Encryption in transit (such as TLS) guards data as it travels across networks.", reward:"Network Sense" },
  { id:"cloud-devops-412", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why protect the cloud root or owner account carefully?", options:["It only opens billing receipts","It cannot change any resources","It is used for daily routine work","It has the highest level of access to everything"], correct:3, explain:"The root account can do anything, so it needs MFA and should be used rarely.", reward:"Access Control" },
  { id:"cloud-devops-413", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why enable MFA on cloud admin accounts?", options:["A stolen password alone will not be enough","Making the console load faster","It removes the need for any password","It encrypts all of the stored files"], correct:0, explain:"MFA adds a second factor so a leaked admin password cannot be used on its own.", reward:"Access Control" },
  { id:"cloud-devops-414", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is an IAM user?", options:["A backup copy of the billing report","An identity that can sign in and use cloud resources","One network port left open by default","A physical key kept in a server room"], correct:1, explain:"IAM users are identities with credentials and permissions for accessing the cloud account.", reward:"Access Control" },
  { id:"cloud-devops-415", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is the principle of least privilege in the cloud?", options:["Give everyone full administrator rights","Remove all access from every account","Give each identity only the access it truly needs","Share one powerful account with the team"], correct:2, explain:"Least privilege limits the damage if an identity is misused or compromised.", reward:"Access Control" },
  { id:"cloud-devops-416", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why rotate cloud access keys periodically?", options:["To make the keys easier to memorize","To speed up every API request","To give the keys nicer-looking names","To limit how long a leaked key stays useful"], correct:3, explain:"Regular rotation shortens the window an exposed key can be abused.", reward:"Secret Safety" },
  { id:"cloud-devops-417", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why avoid hard-coding cloud keys in source code?", options:["Anyone who reads the code could misuse them","It makes the program run more slowly","Keys in code are automatically encrypted","It prevents the app from ever starting"], correct:0, explain:"Hard-coded secrets leak easily through repos; use a secrets manager instead.", reward:"Secret Safety" },
  { id:"cloud-devops-418", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a secrets manager used for?", options:["Backing up large media files","Storing and retrieving secrets securely at runtime","Scanning containers for vulnerabilities","Routing traffic between regions"], correct:1, explain:"A secrets manager keeps credentials out of code and serves them securely when needed.", reward:"Secret Safety" },
  { id:"cloud-devops-419", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why add a .env file to .gitignore?", options:["To make the app start much faster","To delete the file after each commit","To keep local secrets out of the repository","To share the secrets with everyone"], correct:2, explain:"Ignoring .env files helps prevent committing credentials into version control.", reward:"Secret Safety" },
  { id:"cloud-devops-420", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a container image?", options:["A photo stored in object storage","A live running virtual machine","A network diagram of the cluster","A packaged template used to start containers"], correct:3, explain:"An image bundles an app and its dependencies; running it creates a container.", reward:"Container Basics" },
  { id:"cloud-devops-421", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is the effect of running 'docker pull'?", options:["Downloads a container image from a registry","Deletes a running container instantly","Encrypts the host's hard drive","Sends a message to the whole team"], correct:0, explain:"docker pull fetches an image from a registry so it can be run locally or deployed.", reward:"Container Basics" },
  { id:"cloud-devops-422", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why scan container images before deploying?", options:["To make the image colors brighter","To catch known vulnerabilities before production","To rename the image automatically","To slow down the deployment process"], correct:1, explain:"Image scanning finds known flaws and risky contents before they reach production.", reward:"Image Safety" },
  { id:"cloud-devops-423", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why prefer a minimal (slim) base image?", options:["Slim images always run more slowly","Larger images are inherently safer","Fewer packages mean a smaller attack surface","Smaller images cannot be scanned"], correct:2, explain:"Less included software means fewer vulnerabilities to patch and exploit.", reward:"Image Safety" },
  { id:"cloud-devops-424", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why avoid running a container as root?", options:["Root containers always run slower","Non-root containers cannot start","Root is required for every image","A breakout would give the attacker broad control"], correct:3, explain:"Running as a non-root user limits the impact if the container is compromised.", reward:"Container Basics" },
  { id:"cloud-devops-425", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a container registry?", options:["A place to store and share container images","A tool that writes application code","A backup of the user database","A dashboard for billing reports"], correct:0, explain:"Registries hold images so they can be pulled for builds and deployments.", reward:"Registry Sense" },
  { id:"cloud-devops-426", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why restrict who can push to a container registry?", options:["To make image pulls run faster","To stop untrusted images from being deployed","To give images nicer version names","To reduce the registry's storage use"], correct:1, explain:"Limiting push access prevents tampered or malicious images entering deployments.", reward:"Registry Sense" },
  { id:"cloud-devops-427", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does a CI pipeline mainly automate?", options:["Designing the company's logo","Answering customer support tickets","Building and testing code changes","Cooling the data center servers"], correct:2, explain:"Continuous integration automatically builds and tests changes to catch problems early.", reward:"Pipeline Sense" },
  { id:"cloud-devops-428", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why run automated tests in CI?", options:["To make the repository look tidy","To slow developers down on purpose","To delete old branches automatically","To catch bugs before changes are merged"], correct:3, explain:"Automated tests in CI surface defects early, before code is shipped.", reward:"Pipeline Sense" },
  { id:"cloud-devops-429", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a Git commit?", options:["A saved snapshot of changes with a message","A live server that hosts the app","A permanent deletion of all code","A password used to access the repo"], correct:0, explain:"A commit records a point-in-time change set along with a description.", reward:"Version Control" },
  { id:"cloud-devops-430", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a Git branch?", options:["A physical rack of build servers","A separate line of work that won't affect main","A backup of the production database","A schedule for nightly deployments"], correct:1, explain:"Branches let you develop changes in isolation before merging them back.", reward:"Version Control" },
  { id:"cloud-devops-431", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why review pull requests before merging?", options:["To make the repo download faster","To increase the number of commits","To catch bugs and risky changes early","To remove the need for any testing"], correct:2, explain:"Code review adds a human check that catches mistakes and security issues.", reward:"Version Control" },
  { id:"cloud-devops-432", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why protect the main branch with required reviews?", options:["Making the branch load faster","To hide the branch from developers","To delete old commits automatically","So unreviewed code cannot be merged directly"], correct:3, explain:"Branch protection enforces review and checks before changes reach the main line.", reward:"Version Control" },
  { id:"cloud-devops-433", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is infrastructure as code (IaC)?", options:["Defining infrastructure in configuration files","Writing code only on paper first","A backup format for virtual machines","A type of network firewall device"], correct:0, explain:"IaC describes resources in files so they can be created consistently and repeatably.", reward:"IaC Sense" },
  { id:"cloud-devops-434", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why store IaC in version control?", options:["To make deployments run slower","To track changes, review them, and roll back","To give resources nicer names","To use up more repository space"], correct:1, explain:"Versioned IaC gives history, review, and the ability to revert infrastructure changes.", reward:"IaC Sense" },
  { id:"cloud-devops-435", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why does cloud monitoring matter for operations?", options:["To make dashboards more colorful","To slow the systems down on purpose","To detect problems and unusual activity early","To delete logs that take up space"], correct:2, explain:"Monitoring watches health and behavior so issues are caught quickly.", reward:"Monitoring Focus" },
  { id:"cloud-devops-436", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is an alert in monitoring?", options:["A backup of the dashboard layout","A user account for the on-call team","A schedule for rotating passwords","A notification when a metric crosses a threshold"], correct:3, explain:"Alerts fire when monitored conditions exceed limits, prompting investigation.", reward:"Monitoring Focus" },
  { id:"cloud-devops-437", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why are logs valuable in the cloud?", options:["They record events for troubleshooting and audit","They make servers run faster","They store the company's media files","They replace the need for backups"], correct:0, explain:"Logs capture what happened, supporting debugging and incident investigation.", reward:"Log Sense" },
  { id:"cloud-devops-438", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why choose a sensible log retention window?", options:["To delete every log immediately","To keep logs long enough while managing cost","To never keep any logs at all","To slow down every search query"], correct:1, explain:"Retention balances having logs available for investigation against storage cost.", reward:"Log Sense" },
  { id:"cloud-devops-439", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why separate development and production environments?", options:["Creating more colorful dashboards","To use up more cloud servers","So testing and mistakes do not affect live users","To slow the release process down"], correct:2, explain:"Keeping dev apart from prod protects the live system real users depend on.", reward:"Environment Sense" },
  { id:"cloud-devops-440", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why avoid real customer data in development?", options:["Real data makes tests run slower","Dev cannot store any data at all","Real data always corrupts quickly","Dev is less protected, raising the leak risk"], correct:3, explain:"Dev environments are often less hardened, so real data there increases exposure risk.", reward:"Environment Sense" },
  { id:"cloud-devops-441", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What is a rollback after a bad deployment?", options:["Reverting to the last known-good version","Deleting all of the application data","Speeding up the production servers","Encrypting the running application"], correct:0, explain:"A rollback restores the previous working release to recover quickly from a faulty change.", reward:"Rollback Sense" },
  { id:"cloud-devops-442", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why back up data ahead of a risky deployment?", options:["Making the deployment look nicer","So data can be restored if it goes wrong","To use up more disk for fun","To slow the deployment down"], correct:1, explain:"A pre-deployment backup provides a safety net if the change causes data problems.", reward:"Rollback Sense" },
  { id:"cloud-devops-443", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why test changes in staging before production?", options:["To make the change colors brighter","To skip writing any tests at all","To validate them in a production-like setting","To slow down the whole pipeline"], correct:2, explain:"Staging mirrors production so changes can be checked safely before going live.", reward:"Deploy Safety" },
  { id:"cloud-devops-444", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does tagging cloud resources help with?", options:["Making resources run much faster","Encrypting every stored object","Blocking all inbound network traffic","Organizing and tracking ownership and cost"], correct:3, explain:"Tags label resources for cost allocation, ownership, and cleanup.", reward:"Cloud Hygiene" },
  { id:"cloud-devops-445", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why delete unused cloud resources?", options:["To cut cost and reduce the attack surface","To make dashboards more colorful","To increase the monthly bill safely","To slow down the remaining servers"], correct:0, explain:"Idle resources cost money and can become forgotten, unpatched risks.", reward:"Cloud Hygiene" },
  { id:"cloud-devops-446", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does a snapshot of a disk provide?", options:["A live stream of user activity","A point-in-time copy you can restore from","A permanent lock on the disk","A faster network connection"], correct:1, explain:"Snapshots capture disk state so you can restore or clone later.", reward:"Backup Sense" },
  { id:"cloud-devops-447", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why turn on access logging for a storage bucket?", options:["To make objects download faster","To give the bucket a nicer name","To record who accessed objects, aiding audits","To reduce how much it can store"], correct:2, explain:"Access logs show who read or changed objects, supporting audits and investigations.", reward:"Storage Sense" },
  { id:"cloud-devops-448", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why keep production secrets different from dev secrets?", options:["Giving secrets nicer names","To make logins take longer","To use up more storage space","So a dev leak cannot expose production"], correct:3, explain:"Separate secrets ensure a development leak cannot be used against the live system.", reward:"Environment Sense" },
  { id:"cloud-devops-449", tier:"Beginner", topic:"Cloud & DevOps", prompt:"What does 'shared responsibility' clarify in the cloud?", options:["Which security tasks are the provider's vs the customer's","Who designs the company's logo","How fast the internet connection runs","What color the server racks are"], correct:0, explain:"It defines the split of security duties between the provider and the customer.", reward:"Responsibility Sense" },
  { id:"cloud-devops-450", tier:"Beginner", topic:"Cloud & DevOps", prompt:"Why give a CI job only the permissions it needs?", options:["Making builds produce nicer logs","A compromised pipeline can then do less harm","To speed up every single build","To give the job a friendlier name"], correct:1, explain:"Scoped pipeline permissions limit damage if the build system is compromised.", reward:"Pipeline Sense" },
  { id:"cloud-devops-451", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why is a leaked secret in Git history still dangerous after deletion?", options:["Deleting a file always erases history","Git cannot store any secrets at all","The secret remains in past commits until purged","Old commits are encrypted automatically"], correct:2, explain:"Once committed, a secret stays in history; rotate it and purge it from the repo.", reward:"Secret Safety" },
  { id:"cloud-devops-452", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why use short-lived credentials for cloud automation?", options:["Such keys are easier to memorize","They make API calls run faster","They never need any permissions","Limited lifetime reduces damage if they leak"], correct:3, explain:"Short-lived, scoped credentials limit the window and reach of any leak.", reward:"Access Control" },
  { id:"cloud-devops-453", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why prefer IAM roles over long-lived access keys for workloads?", options:["Roles provide temporary credentials that rotate automatically","Roles never expire once created","Keys cannot be used by applications","Roles remove the need for any policy"], correct:0, explain:"Roles issue temporary, auto-rotating credentials, avoiding static keys that can leak.", reward:"Access Control" },
  { id:"cloud-devops-454", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What risk does the instance metadata service pose if misused?", options:["Metadata only ever stores the machine hostname","An SSRF flaw could let an attacker steal instance credentials","Metadata cannot be reached by any running code","It always encrypts every single outgoing request"], correct:1, explain:"If an app is tricked into fetching metadata, exposed credentials can be stolen; use guarded versions.", reward:"Cloud Risk" },
  { id:"cloud-devops-455", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What do security groups or firewall rules control?", options:["How fast the disk reads data","Which user designed the network","Which network traffic can reach a resource","How many logs are kept on disk"], correct:2, explain:"They allow or deny traffic by port, protocol, and source, limiting exposure.", reward:"Network Sense" },
  { id:"cloud-devops-456", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why place databases in a private subnet?", options:["To make queries run more colorfully","To allow anyone to connect freely","To avoid ever needing credentials","To keep them off the public internet"], correct:3, explain:"Private subnets prevent direct internet access, reducing the database's exposure.", reward:"Network Sense" },
  { id:"cloud-devops-457", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is the value of a bastion host or jump box?", options:["A controlled, monitored entry point to private systems","A backup server for media files","A faster cache for web pages","A tool that signs container images"], correct:0, explain:"A hardened bastion centralizes and logs administrative access to private resources.", reward:"Network Sense" },
  { id:"cloud-devops-458", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why pin a container image by digest rather than the latest tag?", options:["Digests make images download faster","The latest tag can change, while a digest is fixed","Tags cannot be used in production","Digests remove the need to scan"], correct:1, explain:"Pinning a digest guarantees you deploy the exact reviewed image, not a moving tag.", reward:"Registry Sense" },
  { id:"cloud-devops-459", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why sign container images?", options:["Making images take up less space","To give images brighter colors","So consumers can verify authenticity and integrity","To skip scanning them for flaws"], correct:2, explain:"Signing lets deployers confirm an image is genuine and unmodified before running it.", reward:"Registry Sense" },
  { id:"cloud-devops-460", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What does Kubernetes RBAC control?", options:["How fast pods start up","The color of the dashboard","The number of nodes available","What actions identities can take in the cluster"], correct:3, explain:"RBAC defines who can do what on which cluster resources, enforcing least privilege.", reward:"Orchestration Sense" },
  { id:"cloud-devops-461", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What does a Kubernetes namespace help with?", options:["Separating and organizing resources in a cluster","Encrypting traffic between regions","Backing up the container registry","Signing every build artifact"], correct:0, explain:"Namespaces partition a cluster to isolate and organize workloads and access.", reward:"Orchestration Sense" },
  { id:"cloud-devops-462", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why is exposing the Kubernetes API publicly risky?", options:["The API only ever shows the pod names","Attackers could control the cluster if it is unprotected","A public API always runs much faster","It cannot accept any commands at all"], correct:1, explain:"An exposed control plane can grant wide control, so restrict and authenticate access.", reward:"Orchestration Sense" },
  { id:"cloud-devops-463", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why use Kubernetes network policies?", options:["To make pods start more quickly","To give pods nicer display names","To limit which pods can talk to each other","To increase the cluster's node count"], correct:2, explain:"Network policies segment pod traffic, reducing lateral movement inside the cluster.", reward:"Orchestration Sense" },
  { id:"cloud-devops-464", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why avoid putting secrets directly in container images?", options:["It makes the image larger only","Secrets in images are encrypted","Images cannot store text at all","Anyone who pulls the image could extract them"], correct:3, explain:"Bake-in secrets are readable by anyone with the image; inject them at runtime instead.", reward:"Container Basics" },
  { id:"cloud-devops-465", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why scan infrastructure-as-code before applying it?", options:["To catch insecure settings before they are real","To make the code run faster","To rename the resources nicely","To slow down provisioning"], correct:0, explain:"IaC scanning finds misconfigurations like open ports before they create live infrastructure.", reward:"IaC Sense" },
  { id:"cloud-devops-466", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why can an IaC state file be sensitive?", options:["State files are always empty","It may contain secrets and resource details","They only store color settings","They cannot be read by anyone"], correct:1, explain:"State can include secrets and infrastructure layout, so it must be stored securely.", reward:"IaC Sense" },
  { id:"cloud-devops-467", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What does immutable infrastructure mean?", options:["Servers that can never be deleted","Disks that cannot store new data","Replacing servers instead of changing them in place","Networks that never carry traffic"], correct:2, explain:"Immutable infra rebuilds from images rather than patching live, reducing drift.", reward:"Deploy Safety" },
  { id:"cloud-devops-468", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is a canary or gradual rollout for?", options:["Making the app icons more colorful","Cooling the production servers","Deleting old log files faster","Releasing to a few users first to catch problems"], correct:3, explain:"Gradual rollouts expose changes to a small group first, limiting blast radius.", reward:"Deploy Safety" },
  { id:"cloud-devops-469", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why is a blue-green deployment useful?", options:["You can switch back quickly if the new version fails","Doubling the monthly bill permanently","It removes the need for testing","It encrypts all user traffic"], correct:0, explain:"Two parallel environments let you shift traffic and roll back fast if needed.", reward:"Deploy Safety" },
  { id:"cloud-devops-470", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why plan database changes carefully for rollback?", options:["Database changes are always trivial","Schema and data changes can be hard to reverse","Rollback is never needed for data","Schemas cannot be changed at all"], correct:1, explain:"Unlike code, data and schema changes may not reverse cleanly, so plan and back up.", reward:"Rollback Sense" },
  { id:"cloud-devops-471", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why protect the CI/CD pipeline as a sensitive system?", options:["It only stores meeting notes","It cannot reach production","It can deploy code and holds powerful secrets","It has no access to any secrets"], correct:2, explain:"Pipelines often hold secrets and can push to production, making them high-value targets.", reward:"Pipeline Sense" },
  { id:"cloud-devops-472", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why limit which branches can trigger production deploys?", options:["To make builds produce nicer logs","To increase the number of branches","To give branches friendlier names","To stop unreviewed code from auto-deploying"], correct:3, explain:"Restricting deploy triggers ensures only approved code reaches production.", reward:"Pipeline Sense" },
  { id:"cloud-devops-473", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why pin dependency versions in a build?", options:["To avoid pulling in unexpected or malicious updates","To make the build look tidier","To speed up the test suite","To reduce the repo's file count"], correct:0, explain:"Pinning versions guards against surprise changes and supply-chain tampering.", reward:"Supply Chain Sense" },
  { id:"cloud-devops-474", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"What is a software bill of materials (SBOM)?", options:["A backup of the source code","A list of the components a build includes","A diagram of the network layout","A schedule for nightly deploys"], correct:1, explain:"An SBOM inventories components so you can find affected software when a flaw appears.", reward:"Supply Chain Sense" },
  { id:"cloud-devops-475", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why use OIDC for CI to access the cloud instead of static keys?", options:["It makes builds run more slowly","It stores keys in the repository","It issues short-lived tokens with no stored secret","It removes all access controls"], correct:2, explain:"Workload identity federation lets CI get temporary credentials without long-lived secrets.", reward:"Access Control" },
  { id:"cloud-devops-476", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why bring logs from many services into one place?", options:["To delete them all faster","To hide them from auditors","To slow the systems down","To search and correlate events in one place"], correct:3, explain:"Central logging lets you connect events across services for troubleshooting and security.", reward:"Log Sense" },
  { id:"cloud-devops-477", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why guard cloud audit logs against tampering?", options:["So they remain trustworthy records of actions","Making charts more colorful","To save a bit of storage","To speed up log searches"], correct:0, explain:"Tamper-resistant audit logs stay reliable as evidence for security and compliance.", reward:"Log Sense" },
  { id:"cloud-devops-478", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why tune monitoring alert thresholds carefully?", options:["Making dashboards load faster","Too sensitive causes noise; too loose misses problems","To create more user accounts","To reduce the number of metrics"], correct:1, explain:"Well-tuned thresholds catch real issues without flooding teams with false alarms.", reward:"Monitoring Focus" },
  { id:"cloud-devops-479", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why re-examine cloud permissions on a regular basis?", options:["Such reviews mainly make logins faster","They mostly add more storage space","Unused or excessive access accumulates and should be trimmed","They simply change the dashboard theme"], correct:2, explain:"Regular reviews catch permission creep, removing access that is no longer needed.", reward:"Access Control" },
  { id:"cloud-devops-480", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why enable encryption keys you manage for sensitive data?", options:["To make files download faster","To give buckets nicer names","To remove the need for backups","To control access and rotation of the keys"], correct:3, explain:"Customer-managed keys give control over who can use them and when they rotate.", reward:"Storage Sense" },
  { id:"cloud-devops-481", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why are overly broad bucket policies risky?", options:["They can unintentionally grant public or wide access","They make uploads run faster","They reduce the storage cost","They encrypt data more strongly"], correct:0, explain:"Broad policies can expose data; scope access narrowly and review it.", reward:"Storage Sense" },
  { id:"cloud-devops-482", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why mask or omit secrets and personal data in logs?", options:["To make logs load faster","To prevent sensitive values from leaking","To give logs nicer colors","To reduce the number of fields"], correct:1, explain:"Sensitive values should be masked or excluded so logs do not become a leak source.", reward:"Log Sense" },
  { id:"cloud-devops-483", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why host internal images in a private registry?", options:["To make pulls run faster","To give images nicer names","To keep proprietary images from public access","To use up more storage"], correct:2, explain:"A private registry restricts access so internal images are not exposed publicly.", reward:"Registry Sense" },
  { id:"cloud-devops-484", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why rescan images periodically, not just once?", options:["Images quietly change their own colors over time","Rescanning mainly slows down image pulls","One single scan covers all future flaws","New vulnerabilities are found in previously clean images"], correct:3, explain:"Vulnerabilities are disclosed continually, so periodic rescans catch newly found issues.", reward:"Image Safety" },
  { id:"cloud-devops-485", tier:"Intermediate", topic:"Cloud & DevOps", prompt:"Why give developers less access in production than in dev?", options:["Production is sensitive, so tighter access lowers risk","Production servers generally run slower","It mainly gives the roles nicer names","It uses up more overall storage space"], correct:0, explain:"Limiting production access protects the live system while developers work freely in dev.", reward:"Environment Sense" },
  { id:"cloud-devops-486", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why is a stolen long-lived cloud access key especially serious?", options:["Keys expire automatically each hour","It can grant ongoing access until someone revokes it","Keys cannot call any cloud APIs","A key only works from one device"], correct:1, explain:"Static keys persist until rotated or revoked, so a leak can mean lasting unauthorized access.", reward:"Access Control" },
  { id:"cloud-devops-487", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why apply organization-wide guardrails (such as service control policies)?", options:["To make each account load faster","To remove the need for any IAM","To set limits no individual account can exceed","To give accounts nicer names"], correct:2, explain:"Account-level guardrails enforce baseline restrictions across an entire organization.", reward:"Governance Sense" },
  { id:"cloud-devops-488", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why separate workloads into multiple cloud accounts or projects?", options:["To make billing reports colorful","To remove the need for monitoring","To share one key across everything","To contain blast radius and isolate environments"], correct:3, explain:"Account separation limits how far a compromise or mistake can spread.", reward:"Governance Sense" },
  { id:"cloud-devops-489", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why is supply-chain security critical in CI/CD?", options:["A compromised dependency or build can ship malware widely","Builds never use any outside code at all","Pipelines can never reach the production systems","Dependencies are always fully trusted"], correct:0, explain:"Attackers target build inputs and tools to insert malicious code into many downstream users.", reward:"Supply Chain Sense" },
  { id:"cloud-devops-490", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why verify image signatures at deploy time, not just at build?", options:["Build-time checks cover all risk","To ensure the image was not swapped after building","Signatures cannot be verified later","Deploys never pull new images"], correct:1, explain:"Admission-time verification confirms only trusted, unmodified images actually run.", reward:"Registry Sense" },
  { id:"cloud-devops-491", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why use admission control in Kubernetes?", options:["To make pods start faster only","To replace all cluster logging","To enforce policy on what workloads may run","To give nodes nicer names"], correct:2, explain:"Admission controllers can block non-compliant or unsigned workloads before they run.", reward:"Orchestration Sense" },
  { id:"cloud-devops-492", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why is detecting infrastructure drift important?", options:["Drift makes deployments faster","IaC can never match reality","Drift removes the need for review","Real resources may differ from the reviewed IaC"], correct:3, explain:"Drift means manual changes bypassed review; detecting it restores a known, safe state.", reward:"IaC Sense" },
  { id:"cloud-devops-493", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why prefer ephemeral build runners for CI?", options:["A fresh runner limits persistence of a compromise","Such runners keep secrets forever","They cannot run any builds","They never need any network"], correct:0, explain:"Disposable runners reduce the chance that a compromise lingers between builds.", reward:"Pipeline Sense" },
  { id:"cloud-devops-494", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why is logging the control plane (API audit) essential?", options:["It only stores billing totals","It records who changed cloud resources and when","It cannot capture admin actions","It replaces all application logs"], correct:1, explain:"Control-plane audit logs are key evidence for investigating cloud account activity.", reward:"Log Sense" },
  { id:"cloud-devops-495", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why design for recovery objectives (RTO and RPO)?", options:["They set the dashboard colors","They remove the need for backups","They define acceptable downtime and data loss","They only affect billing reports"], correct:2, explain:"RTO and RPO drive backup frequency and failover design to meet recovery goals.", reward:"Resilience Sense" },
  { id:"cloud-devops-496", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why protect internet-facing services with a WAF and rate limits?", options:["To make pages load more colorfully","To remove the need for patching","To disable all legitimate traffic","To filter malicious requests and absorb abuse"], correct:3, explain:"A web application firewall and rate limiting reduce common attacks and abusive load.", reward:"Edge Defense" },
  { id:"cloud-devops-497", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why rotate and scope cloud secrets even in a secrets manager?", options:["A leaked secret still does less harm if narrow and short-lived","Secrets managers can never possibly leak","Rotation always breaks every single application","Scope has no real effect on the risk"], correct:0, explain:"Defense in depth: even managed secrets benefit from least privilege and rotation.", reward:"Secret Safety" },
  { id:"cloud-devops-498", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why correlate cloud, identity, and network logs during an incident?", options:["One log source shows everything","Each source reveals a different part of the activity","Correlation hides the timeline","More sources guarantee attribution"], correct:1, explain:"Correlating sources links account changes, logins, and traffic into a fuller picture.", reward:"Investigation Path" },
  { id:"cloud-devops-499", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why treat a public bucket exposure as a possible data breach?", options:["Public buckets cannot be read","Exposure is only a billing issue","Unknown parties may have copied the data already","The data is safe once re-secured"], correct:2, explain:"Once data is publicly reachable, you must assume it may have been accessed and respond accordingly.", reward:"Incident Sense" },
  { id:"cloud-devops-500", tier:"Advanced", topic:"Cloud & DevOps", prompt:"Why is least privilege especially important for CI/CD service identities?", options:["They are never used by attackers","They always run without any access","They cannot deploy to production","They are powerful, automated, and attractive targets"], correct:3, explain:"Pipeline identities can change production, so tightly scoping them limits compromise impact.", reward:"Access Control" },
];

if (typeof module !== "undefined" && module.exports) module.exports = CLOUD_DEVOPS_QUESTIONS;
